export default [{"id":158,"question":"نريد بعض التفصيل في حكم اللحم المثلج والدّجاج؟","title":"ما حكم الدجاج واللحوم المجمّدة المستوردة؟","answer":"الجواب: هذا كثر الكلام فيه، اللحم المثلَّج والمصبَّر وغيره من البلاد الخارجية كتب فيه كثيرٌ من الكتاب وطلبة العلم، وأنا لا أزال على رأي قد قلتُه غير مرةٍ وأعلنته غير مرة في \"نور على الدرب\" وفي غير ذلك، ولعله في بعض الكتابات أيضًا، وهو أني أرى أن الوارد قسمان: ما يرد من بلاد الشيوعيين والوثنيين، وهذا لا يجوز استعماله أبدًا حتى نعلم أنَّ الذي تولَّاه مسلمون أو أهل الكتاب؛ فلا بأس إذا تولاه مسلمون أو أهل كتابٍ، فإن جاء من بلاد وثنيين وشيوعيين لكن تولاه مسلمون أو كتابيون، وذُبح الذبح الشرعي؛ فلا بأس في ذلك.\nأما ما يرد من بلاد أهل الكتاب: إنجلترا، وفرنسا، وأمريكا، وأشباههم، فالأصل فيه الحلّ، هذا هو الأصل؛ لأنَّ الله أباح لنا طعام أهل الكتاب، فالأصل حلّه، وإنْ وجد شركات ومجازر تذبح لغير الشرع، لكن الأصل حله لنا، فلا يجوز أن نُحرم ذلك إلا بدليلٍ، فما ورد إلينا فهو حلالٌ منهم، إلا إذا علمنا يقينًا أنَّ هذا الشيء -هذه العلبة أو هذا المصبَّر- جاء من مجزرة تخنق، أو تضرب الرأس حتى يموت الحيوان، أو ما أشبه ذلك. أما إذا لم نعلم أنَّ هذه المجزرة وهذه الشركة تفعل هذا؛ فالأصل الحلّ في طعام أهل الكتاب من اليهود والنصارى، هذا هو الأصل.\nفكما أننا نقول في ذبائح المسلمين: الأصل فيها الحل، وإن كان بعض المسلمين قد يتساهل، وقد يكون فاسقًا، وقد يكون متساهلًا، لكن الأصل حلّ ذبائح المسلمين حتى نعلم أنَّ هذا المسلم خنقها أو قتلها بضرب رأسها وقيذة أو ما أشبه ذلك، فهكذا نقول في أهل الكتاب، سواء بسواء، وإن اشتهر فيما بينهم وجود مَن يخنقها -لوجود مَن يضرب رأسها ويصعقها- فلا يكفي هذا في تحريم الجميع، بل نُحرم ما علمنا، ولا نحرم ما لم نعلم، ونقول في ذبيحتهم: الأصل فيها الحلّ حتى نعلم أنَّ هذه المصبَّرة أو أن هذه الذبيحة أو أن هذا المبرَّد قد ذُبح على غير الشرع.","link":"https://binbaz.org.sa/fatwas/3695/ما-حكم-الدجاج-واللحوم-المجمدة-المستوردة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0151.mp3","categories":["الذكاة والصيد"]},{"id":486,"question":"رجل صدم شاة بسيارة فلما خرج من السيارة وجدها حية وذبحها فهل تحل له؟","title":"حكم شاةٍ صدمتها سيارة ثم ذُبحت وهي حية","answer":"الجواب: تحل لأهلها\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6245/حكم-شاة-صدمتها-سيارة-ثم-ذبحت-وهي-حية","audio":"https://files.zadapps.info/binbaz.org.sa/shah047.mp3","categories":["الذكاة والصيد"]},{"id":502,"question":"الأحاديث التي فيها النهي عن الفَرَعِ والعَتيرَة، والأحاديث التي فيها الرخصة فيها، ما الجمع بين النهي والرخصة؟","title":"ما حكم الفَرَعِ والعَتيرَة؟","answer":"الجواب: الفَرَعِ والعَتيرَةِ من أمور الجاهلية، وفي الحديث الصحيح: لا فرع في الإسلام.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6281/ما-حكم-الفرع-والعتيرة","audio":"https://files.zadapps.info/binbaz.org.sa/maram066 - 02 - .mp3","categories":["الذكاة والصيد"]},{"id":802,"question":"يوجد سبع يُسمَّى: النيص، أو كبير القنافذ، فما حكم أكله؟ مع الدليل.","title":"حكم صيد النيص (القنفذ) وأكله؟","answer":"الجواب: هذا ليس بسبعٍ، هذا صيدٌ، ليس بسبعٍ، وليس يفترس، وإنما هو صيدٌ له شوك على ظهره طويل، ويُسمَّى: النيص، ويُسمَّى: القنفذ، ويُسمَّى: الدلدل، يأكل الشجر والنبات، فهو صيدٌ على الصحيح، ولا حرج فيه.","link":"https://binbaz.org.sa/fatwas/20794/حكم-صيد-النيص-القنفذ-واكله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0623حكم أكل النيص؟ ابن باز فتاوى المحاضرات.mp3","categories":["الذكاة والصيد"]},{"id":866,"question":"ما حكم شراء اللحوم من جزارٍ يُقيم الولائم على الأضرحة والقباب ويعتقد فيها؟","title":"حكم الشراء من جزارٍ يُقيم ولائم للأضرحة","answer":"الجواب: لا يُشترى من هذا لحم، هذا ظاهره الشرك، لا يشتري منه لحوم، لا يشتري اللحوم إلا من أهل التوحيد، وإلا اذبح لنفسك، أو اشترِ السمك.","link":"https://binbaz.org.sa/fatwas/20905/حكم-الشراء-من-جزار-يقيم-ولاىم-للاضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0700ما حكم شراء اللحوم من جزَّار يقيم الولائم على الأضرحة والقباب ويعتقد فيها؟ابن باز.mp3","categories":["الذكاة والصيد"]},{"id":907,"question":"في قوله تبارك وتعالى: وَلَا تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهِ الآية [الأنعام:121] هل المقصود بالذكر عند الذبح أو عند الأكل؟","title":"معنى: {ولا تأكلوا مما لم يذكر اسم الله عليه}","answer":"الجواب: المقصود عند الذبح، إذا ذبحَ ولم يُسمّ الله، أو صاد ولم يُسم الله؛ لا تحلّ ذبيحته، ولا تُؤكل، سواء كان مسلمًا أو كتابيًّا، لكن إذا كان نسيانًا أو تركها جهلًا فإنها تحلّ، أما إذا تعمَّد ذلك وهو يعلم الحكم الشرعي فإنها لا تحلّ ذبيحته؛ للآية الكريمة: فَكُلُوا مِمَّا ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ [الأنعام:118]، ولما جاء في الأحاديث الصَّحيحة في قوله ﷺ: إذا رميتَ السهم فاذكر اسم الله، إذا أرسلتَ كلبَك فاذكر اسم الله مع عموم الآية: وَلَا تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهِ.\nفالمقصود إذا تركها عمدًا، أما النسيان فالله يقول: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، قال الله: قد فعلتُ، والجاهل في حكم الناسي.","link":"https://binbaz.org.sa/fatwas/20936/معنى-ولا-تاكلوا-مما-لم-يذكر-اسم-الله-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0732في قوله تعالى ولا تأكلوا ممالم يذكراسم الله عليه هل المقصود الذكر عند الذبح أو عند الأكل؟ابن باز.mp3","categories":["الذكاة والصيد"]},{"id":1768,"question":"رجل مسلم ذبح ذبيحةً وما ذكر اسم الله ناسيًا، ما حكمه؟","title":"حكم من نسي التسمية على ذبيحته","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/21875/حكم-من-نسي-التسمية-على-ذبيحته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من نسي أن يذكر الله على ذبيحته.mp3","categories":["الذكاة والصيد"]},{"id":3171,"question":"أناس يصيدون عن طريق الصقور، يقولون عند تدريبنا الصقر نجعل فريسة أرنب أو شيء، ثم يأتي هذا الصقر ويتعلم عليه يقولون: هل هذا من...؟","title":"حكم اتخاذ حيوان فريسة لتعليم الحيوان المُعَلَّم","answer":"الجواب: إذا كان حيًّا ما يجوز، أما ميت فلا بأس، مذبوح فلا بأس.\nس: لعموم الحديث؟\nالشيخ: الرسول ﷺ نهى عن اتخاذ الروح غرضًا.","link":"https://binbaz.org.sa/fatwas/23334/حكم-اتخاذ-حيوان-فريسة-لتعليم-الحيوان-المعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صيد الحيوان المعلم.mp3","categories":["الذكاة والصيد"]},{"id":3807,"question":"حكم الصيد بالخذف؟","title":"ما حكم الصيد بالخذف؟","answer":"الجواب: ما يحل، الخذف آلة منهيٌّ عنها، تقتل بثقلها، بقوتها.","link":"https://binbaz.org.sa/fatwas/24008/ما-حكم-الصيد-بالخذف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصيد بالخذف.mp3","categories":["الذكاة والصيد"]},{"id":3810,"question":"قول ابن عباس في أول الباب: من ترك التسمية ناسيًا...؟","title":"ما حكم ذبيحة مَنْ ترك التسمية ناسيًا؟","answer":"الجواب: نعم عند عامة أهل العلم كالإجماع في حلها..... حكى ابن جرير إجماع أهل العلم.....، رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا، مثل ما قال البخاري رحمه الله من ترك التسمية فليس بفاسق..... كالإجماع، يعني القول بالتحريم شاذ.\nس: إذا كان ما فيها حركة إلا العين؟\nالشيخ: المقصود لا بدّ من تحقق الحياة.","link":"https://binbaz.org.sa/fatwas/24011/ما-حكم-ذبيحة-من-ترك-التسمية-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من ترك التسمية عند الذبح.mp3","categories":["الذكاة والصيد"]},{"id":3811,"question":"بمناسبة ذكر الوقيذة، إذا تردت مثل الغنم وقبل أن تموت بقليل يعني ذُكيت وهي قريبة من الموت؟","title":"حكم الذبيحة التي تُذكّى وهي قريبة من الموت","answer":"الجواب: مثل ما قال تعالى: إِلَّا مَا ذَكَّيْتُمْ إذا ذُكيت وبها حياة.\nس: ولو قبل الموت بلحظة.\nالشيخ: ولو، نعم، ما دام فيها حياة، تحركت رجل أو رأس أو أذن.","link":"https://binbaz.org.sa/fatwas/24012/حكم-الذبيحة-التي-تذكى-وهي-قريبة-من-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أحل لحم ماذُكِّيت وهي قريبة من الموت.mp3","categories":["الذكاة والصيد"]},{"id":3812,"question":"الذّبح بالآلات جُملة؟","title":"ما حكم ما يُذبح بالآلات؟","answer":"الجواب: مثل ما قال النبي ﷺ: ما أنهر الدم وذكر اسم الله فكل، ليس السن والظفر.","link":"https://binbaz.org.sa/fatwas/24013/ما-حكم-ما-يذبح-بالالات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ما يذبح بالآلات.mp3","categories":["الذكاة والصيد"]},{"id":3813,"question":"الواقع أن كثيرًا من الذين يذبحون ما يكسر الرقبة لكن إذا ذبح يدخل السكين إلى النخاع فيقطعه بدون كسر بعد ذلك تسكن الحركة..؟","title":"حكم كسر الرأس في ذبح الأنعام","answer":"الجواب: ظاهر هذا كله أنه ينبغي ترك هذا، وأنه يكتفى بقطع الحلقوم والمرئ والودجين وبس، يكفي لا يدخلها ولا يكسر الرأس، لكن لو فعل أجزأ، لو قطع الرأس مرة واحدة أجزأ؛ لأن المقصود حصل، لكن ترك ذلك على ما يروى عن عمر وعن ابن عمر وعن سعيد بن المسيب مرسلاً تركه أوْلى، يعني أقل أحواله الكراهة.","link":"https://binbaz.org.sa/fatwas/24014/حكم-كسر-الراس-في-ذبح-الانعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسأئل متفرقة في ذبح الأنعام.mp3","categories":["الذكاة والصيد"]},{"id":3814,"question":"في المذابح يسمون على الأولى والباقي يتركون؟","title":"هل تكفي التسمية لعدة ذبائح على الأولى منها؟","answer":"الجواب: ... إذا قصد الجميع كفى.\nس: هو شخص الذي يذبح عن طريقة الآلة، في المرة الأولى يُسمي، وفي الباقي ما يسمي عليها؟\nالشيخ: يعني يذبح بيده، وإلا الآلة التي تذبح؟\nس: الآلة تمر وهو يذبح بيده؟ آلة تدور وكلما مرت ذبح بيده.\nالشيخ:..... إذا سمى على الجميع يكفي، إذا سمى على الأولى قصده الجميع كفى إن شاء الله؛ لأنها تزهق أرواحها بسرعة.","link":"https://binbaz.org.sa/fatwas/24015/هل-تكفي-التسمية-لعدة-ذباىح-على-الاولى-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التسمية على أولى الذبائح فقط، وترك الباقي.mp3","categories":["الذكاة والصيد"]},{"id":3815,"question":"يجوز الذبح بالآلة الكهربائية؟","title":"ما حكم الذبح بالآلة الكهربائية؟","answer":"الجواب: نعم، إذا كان محدودًا، إذا كان بحدها، نعم.","link":"https://binbaz.org.sa/fatwas/24016/ما-حكم-الذبح-بالالة-الكهرباىية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الذبح بالآلة الكهربائية.mp3","categories":["الذكاة والصيد"]},{"id":3818,"question":"هل تذبح الخيل أم تنحر؟","title":"هل تُذبح الخيل أم تُنحر؟","answer":"الجواب: تُذبح ذبحًا مثل البقرة، ولو نحرها أجزأ، مثل ما تقدم، كله جائز.","link":"https://binbaz.org.sa/fatwas/24019/هل-تذبح-الخيل-ام-تنحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الخيل هل تذبح أم تنحر.mp3","categories":["الذكاة والصيد"]},{"id":4355,"question":"الجربوع ما يصاد إلا بعصا؛ لأنه سريع، ما يؤكل؟","title":"هل يحلُّ أكلُ الجربوع بعد صيده بالعصا؟","answer":"الجواب: الجربوع لا بأس به.\nالطالب: ما يصاد إلا بعصا؟\nالشيخ: الجربوع لا بأس، إذا ضربته بالعصا ومات صار حرامًا، صار ميتة.\nس: ما يؤكل؟\nج: لا، لابد أن يذبح ذبحًا.\nالطالب: أخاف يموت، أول ما تطقه يموت؟\nالشيخ: لا إذا طقيته ومات؛ لا تأكله.","link":"https://binbaz.org.sa/fatwas/24632/هل-يحل-اكل-الجربوع-بعد-صيده-بالعصا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في صيد الجربوع.mp3","categories":["الذكاة والصيد"]},{"id":4368,"question":"يكفي في التذكية قطع الحلقوم والمريء، أم لا بد من أحد الودجين؟","title":"هل يكفي في التذكية قطع الحلقوم والمريء؟","answer":"الجواب: يكفي، لكن إذا قطع أحد الودجين أو كليهما أكمل، والصواب يجزئ الحلقوم والمري، لكن إذا قطع الودجين أو أحدهما يكون أكمل.","link":"https://binbaz.org.sa/fatwas/24645/هل-يكفي-في-التذكية-قطع-الحلقوم-والمريء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التذكية.mp3","categories":["الذكاة والصيد"]},{"id":4678,"question":"الضبع أليست من ذوات الأنياب؟","title":"حكم قتل وأكل الضبع؟","answer":"الجواب: لكن مُستثناة، يقولون ضروس، ما هو بذاك، هي شيء مستدير تطحن طحنًا.\nس: وعلى هذا يجوز قتلها؟\nج: نعم، هي صيد.\nس: ما له أنياب الضبع؟\nج: بلغني أنها ما لها أنياب، وأنه يكون لها ضرس كبير مُستدير تطحن عليه طحنًا .......\nس: الضبع يأكل السباع المُفترسة؟\nج: مُستثنى بالنص.","link":"https://binbaz.org.sa/fatwas/24970/حكم-قتل-واكل-الضبع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قتل الضبع في الحج.mp3","categories":["الذكاة والصيد"]},{"id":4858,"question":"بعض الدول تذبح الدجاج بالصعق الكهربائي أو بالخنق فكيف يفعل الشخص إذا لم يجد إلا هذه الوسيلة، يأكل منها؟","title":"حكم الأكل مما ذُبح بالصعق أو الخنق؟","answer":"لا، هذه ميتة.\nس: وهل لا بدّ من ثبوت هذا لديه؟\nج: إن كانت من ذبائح أهل الكتاب تحل له، إلا أن يثبت له أن ذبحت بغير الشرع كالصعق أو بغيره، أما إذا كان من ذبيحة المجوس أو الوثنيين فهذه تحرم مطلقًا.","link":"https://binbaz.org.sa/fatwas/25324/حكم-الاكل-مما-ذبح-بالصعق-او-الخنق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأكل مما ذُبح بالصعق الكهربائي أو الخنق.mp3","categories":["أحكام الحيوان","الذكاة والصيد"]},{"id":5762,"question":"عندما أذبح مائة خروف مثلًا، هل تكفي التسمية الواحدة، أم لا؟","title":"ذبح مجموعة من الغنم بتسمية واحدة","answer":"الجواب: كل خروف يحتاج إلى تسمية، وإذا كانت آلة تذبحها بسرعة، فسمى عليها جميعًا، نرجو أنه يكفي -إن شاء الله- ولكن إن كان  يذبحها بيده اليمنى سمى.  وإذا كان بآلة تمر على حلوقهم بسرعة، وسمى على هذه الآلة بسرعة، نرجو أن يكفي ذلك.","link":"https://binbaz.org.sa/fatwas/1093/ذبح-مجموعة-من-الغنم-بتسمية-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_99.mp3","categories":["الذكاة والصيد"]},{"id":5898,"question":"ما الحكم في ذبيحة تارك الصلاة؟ هل يجوز الأكل منها؟","title":"هل يجوز الأكل من ذبيحة تارك الصلاة؟","answer":"الجواب: الصحيح أن تارك الصلاة متعمدًا، ولو كسلًا من غير جحد للوجوب كافر كفرًا أكبر، هذا الصحيح من قول العلماء، ودليل ذلك قول النبي -عليه الصلاة والسلام- في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقال -عليه الصلاة والسلام- : بين الرجل وبين الكفر، والشرك ترك الصلاة.  وقال في أمراء السوء لما سأله الصحابة عن جهادهم، قال: إلا إن تروا كفرًا بواحًا، عندكم من الله فيه برهان وفي لفظ آخر: ما أقاموا فيكم الصلاة. فدل على أن ترك إقامة الصلاة كفر بواح؛ لأنه جعله بمنزلة الكفر البواح، فعلم أن عدم إقامة الصلاة كفر بواح، ما قال ما جحدوا الصلاة، قال: ما أقاموا، فالذي يتركها، ولا يقيمها ليس من المسلمين، هذا هو الصواب.  وذهب جمع من أهل العلم إلى أنه كفره كفر أصغر، لا كفر أكبر، وأن ذبيحته تحل، ونكاحه صحيح للمسلمة؛ لأن كفره كفرًا أصغر، مثل كفر يسير الرياء، ومثل كفر من حلف بغير الله، من جرى على لسانه الحلف بغير الله، أو مثل من قال: لولا الله وفلان، أو ما أشبه ذلك، وقالوا: إن هذا معنى الحديث، وليس معناه أنه كافر كفرًا أكبر. والصواب: القول الأول؛ لأن الرسول أطلق الكفر، وجاء بلفظ (أل) بينه وبين الكفر، والشرك، والكفر المعرف، والشرك المعرف هو الشرك الأكبر، ولأدلة أخرى، والله جعل الصلاة على لسان نبيه عمود الإسلام. فالمقصود: أن تاركها على الأصح كافر كفرًا أكبر؛ وعلى هذا تكون ذبيحته غير شرعية، تكون ذبيحته ميتة، ولا ينبغي أن يواكل، ولا تجاب دعوته، ولا يرد عليه السلام، يهجر.","link":"https://binbaz.org.sa/fatwas/1235/هل-يجوز-الاكل-من-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_232.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":5915,"question":"ما الحكم في ذبيحة تارك الصلاة؟ هل يجوز الأكل منها؟","title":"هل يجوز الأكل من ذبيحة تارك الصلاة؟","answer":"الجواب: الصحيح أن تارك الصلاة متعمدًا، ولو كسلًا من غير جحد للوجوب كافر كفرًا أكبر، هذا الصحيح من قول العلماء، ودليل ذلك قول النبي -عليه الصلاة والسلام- في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقال -عليه الصلاة والسلام- : بين الرجل وبين الكفر، والشرك ترك الصلاة.  وقال في أمراء السوء لما سأله الصحابة عن جهادهم، قال: إلا إن تروا كفرًا بواحًا، عندكم من الله فيه برهان وفي لفظ آخر: ما أقاموا فيكم الصلاة. فدل على أن ترك إقامة الصلاة كفر بواح؛ لأنه جعله بمنزلة الكفر البواح، فعلم أن عدم إقامة الصلاة كفر بواح، ما قال ما جحدوا الصلاة، قال: ما أقاموا، فالذي يتركها، ولا يقيمها ليس من المسلمين، هذا هو الصواب.  وذهب جمع من أهل العلم إلى أنه كفره كفر أصغر، لا كفر أكبر، وأن ذبيحته تحل، ونكاحه صحيح للمسلمة؛ لأن كفره كفرًا أصغر، مثل كفر يسير الرياء، ومثل كفر من حلف بغير الله، من جرى على لسانه الحلف بغير الله، أو مثل من قال: لولا الله وفلان، أو ما أشبه ذلك، وقالوا: إن هذا معنى الحديث، وليس معناه أنه كافر كفرًا أكبر. والصواب: القول الأول؛ لأن الرسول أطلق الكفر، وجاء بلفظ (أل) بينه وبين الكفر، والشرك، والكفر المعرف، والشرك المعرف هو الشرك الأكبر، ولأدلة أخرى، والله جعل الصلاة على لسان نبيه عمود الإسلام. فالمقصود: أن تاركها على الأصح كافر كفرًا أكبر؛ وعلى هذا تكون ذبيحته غير شرعية، تكون ذبيحته ميتة، ولا ينبغي أن يواكل، ولا تجاب دعوته، ولا يرد عليه السلام، يهجر.","link":"https://binbaz.org.sa/fatwas/1235/هل-يجوز-الاكل-من-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_232.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":5990,"question":"ما حكم من قتل أرنبًا، أو غزالة، أو طيرًا بحجر، أو عصا، أو صدمه بالسيارة، فما حكم الأكل من هذا؟","title":"حكم أكل صيد قتل بغير محدد","answer":"الجواب: ما يأكل منه إذا صدمه بالسيارة، أو بحجر، أو بعصا، ما يأكل، يكون موقوذًا لا يحل، لكن إذا قتله بمسدس، أو أطلق عليه كلب معلم، وقتله، أو رماه بالرصاص، ويقول: بسم الله والله أكبر عند الرمي. السؤال: وبالحجر طيب؟ الجواب: إذا كان الحجر له حد؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1370/حكم-اكل-صيد-قتل-بغير-محدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_328.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":5991,"question":"ما حكم من قتل أرنبًا، أو غزالة، أو طيرًا بحجر، أو عصا، أو صدمه بالسيارة، فما حكم الأكل من هذا؟","title":"حكم أكل صيد قتل بغير محدد","answer":"الجواب: ما يأكل منه إذا صدمه بالسيارة، أو بحجر، أو بعصا، ما يأكل، يكون موقوذًا لا يحل، لكن إذا قتله بمسدس، أو أطلق عليه كلب معلم، وقتله، أو رماه بالرصاص، ويقول: بسم الله والله أكبر عند الرمي. السؤال: وبالحجر طيب؟ الجواب: إذا كان الحجر له حد؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1370/حكم-اكل-صيد-قتل-بغير-محدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_328.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":6003,"question":"ما حكم أكل اللحوم المستوردة مثل لحوم الدجاج، والأغنام، وغيرها، نرجو أن يكون الجواب كافيًا شافيًا؟ وإذا كان في الجواب تفصيل بالنسبة لطريقة، وكيفية الذبح، فكيف نحصل على المعلومات في ذلك؟","title":"حكم أكل اللحوم المستوردة من بلاد الكفار","answer":"الجواب:  هذا يكثر عنه السؤال كثيرًا، أكل المستورد من اللحوم هذا السؤال.. كثير جدًا، والحاجة ماسة إلى إحكام هذا الأمر من جهتين: من جهة ضبط المستورد، والعناية بالمستورد، ومن جهة تكليف الحكومة في كل بلد للمستوردين أن يستوردوا على بصيرة، وألا يستوردوا إلا لحومًا معروفة، قد ذبحت على الطريقة الإسلامية، وتولى ذبحها من يباح ذبحه من المسلمين، أو أهل الكتاب. هذه المسألة لا بدّ فيها من التفصيل، والذين يستوردون اللحوم الآن ليس عندنا معلومات كافية على أنهم قد اعتنوا بالشروط الكافية، وإن كان المعلوم من وزارة التجارة هنا: أن المستورد قد عني به، وأنه لا يستورد إلا الشيء الذي يباح أكله، هذا هو قولهم.  ولكن المؤمن، والمسلم قد يشك في كثير من هذه الأشياء؛ لأن المستورد من البلاد الشيوعية فيه خطر؛ ولأن المسلمون هناك مستضعفون، ومضطهدون؛ فيخشى أن لا يكونوا تولوا هذا الشيء، ويخشى أن لا يكون تولاه منهم من هو معروف بالتوحيد، والاستقامة، هذه أشياء توجب التبصر في هذا المقام. وكذلك ما يستورد من جهة الغرب من بلاد النصارى فيه شركات تذبح ذبح غير إسلامي، وفي شركات تذبح ذبحًا إسلاميًا، فالمقام فيه خطورة، والاحتياط للمؤمن ترك هذه الأشياء، وألا يأكل إلا من شيء معروف من بلاده، أو مذبوح في بلاده، أو ذبحه هو. ولكن إذا عرف أن هذا المستورد من طعام أهل الكتاب، ومما ذبحه أهل الكتاب، ولم يبلغه عن شيء يوجب تحريمه فالأصل إباحته؛ لأن الله أباح لنا طعام أهل الكتاب، فإذا عرف أن هذا المستورد من بلاد النصارى، من لندن، من فرنسا، من الدنمارك، من أشباه ذلك، وهو مقطوع الرؤوس، ولا يعلم عن هذه الشركة التي استوردت، أو هذه الجهة التي استوردت، لا يعرف ذلك، فالأصل الحل في هذا، هذا هو الأصل. ومتى عرف أن هذه الشركة التي وردت هذا اللحم أنها لا تقطع الرأس إلا بعد ذلك، بعد الموت، أو أنها تذبح بالطريقة غير الإسلامية، كالخنق، ونحو ذلك، أو رض رأسه حتى يموت، أو ما أشبه ذلك؛ فإنه لا يأكل  ما علم حرمته، إذا علم أنه منخنقة، أو موقوذة، وإذا شك في ذلك، وأحب أن يحتاط لنفسه، فمثل ما قال النبي: دع ما يريبك إلى ما لا يريبك من اتقى الشبهات؛ فقد استبرأ لدينه، وعرضه.  ولكن لا نحرم ما أحله الله، فلا نحرم طعام أهل الكتاب، بل هو حل لنا حتى نعلم أنه ...، وأما طعام الشيوعيين، والوثنين من المجوس، وغيرهم؛ فهو حرام بلا شك، إلا أن يتولاه مسلم، أو كتابي، يتولى ذبحه.","link":"https://binbaz.org.sa/fatwas/1416/حكم-اكل-اللحوم-المستوردة-من-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_360.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":6006,"question":"ما حكم أكل اللحوم المستوردة مثل لحوم الدجاج، والأغنام، وغيرها، نرجو أن يكون الجواب كافيًا شافيًا؟ وإذا كان في الجواب تفصيل بالنسبة لطريقة، وكيفية الذبح، فكيف نحصل على المعلومات في ذلك؟","title":"حكم أكل اللحوم المستوردة من بلاد الكفار","answer":"الجواب:  هذا يكثر عنه السؤال كثيرًا، أكل المستورد من اللحوم هذا السؤال.. كثير جدًا، والحاجة ماسة إلى إحكام هذا الأمر من جهتين: من جهة ضبط المستورد، والعناية بالمستورد، ومن جهة تكليف الحكومة في كل بلد للمستوردين أن يستوردوا على بصيرة، وألا يستوردوا إلا لحومًا معروفة، قد ذبحت على الطريقة الإسلامية، وتولى ذبحها من يباح ذبحه من المسلمين، أو أهل الكتاب. هذه المسألة لا بدّ فيها من التفصيل، والذين يستوردون اللحوم الآن ليس عندنا معلومات كافية على أنهم قد اعتنوا بالشروط الكافية، وإن كان المعلوم من وزارة التجارة هنا: أن المستورد قد عني به، وأنه لا يستورد إلا الشيء الذي يباح أكله، هذا هو قولهم.  ولكن المؤمن، والمسلم قد يشك في كثير من هذه الأشياء؛ لأن المستورد من البلاد الشيوعية فيه خطر؛ ولأن المسلمون هناك مستضعفون، ومضطهدون؛ فيخشى أن لا يكونوا تولوا هذا الشيء، ويخشى أن لا يكون تولاه منهم من هو معروف بالتوحيد، والاستقامة، هذه أشياء توجب التبصر في هذا المقام. وكذلك ما يستورد من جهة الغرب من بلاد النصارى فيه شركات تذبح ذبح غير إسلامي، وفي شركات تذبح ذبحًا إسلاميًا، فالمقام فيه خطورة، والاحتياط للمؤمن ترك هذه الأشياء، وألا يأكل إلا من شيء معروف من بلاده، أو مذبوح في بلاده، أو ذبحه هو. ولكن إذا عرف أن هذا المستورد من طعام أهل الكتاب، ومما ذبحه أهل الكتاب، ولم يبلغه عن شيء يوجب تحريمه فالأصل إباحته؛ لأن الله أباح لنا طعام أهل الكتاب، فإذا عرف أن هذا المستورد من بلاد النصارى، من لندن، من فرنسا، من الدنمارك، من أشباه ذلك، وهو مقطوع الرؤوس، ولا يعلم عن هذه الشركة التي استوردت، أو هذه الجهة التي استوردت، لا يعرف ذلك، فالأصل الحل في هذا، هذا هو الأصل. ومتى عرف أن هذه الشركة التي وردت هذا اللحم أنها لا تقطع الرأس إلا بعد ذلك، بعد الموت، أو أنها تذبح بالطريقة غير الإسلامية، كالخنق، ونحو ذلك، أو رض رأسه حتى يموت، أو ما أشبه ذلك؛ فإنه لا يأكل  ما علم حرمته، إذا علم أنه منخنقة، أو موقوذة، وإذا شك في ذلك، وأحب أن يحتاط لنفسه، فمثل ما قال النبي: دع ما يريبك إلى ما لا يريبك من اتقى الشبهات؛ فقد استبرأ لدينه، وعرضه.  ولكن لا نحرم ما أحله الله، فلا نحرم طعام أهل الكتاب، بل هو حل لنا حتى نعلم أنه ...، وأما طعام الشيوعيين، والوثنين من المجوس، وغيرهم؛ فهو حرام بلا شك، إلا أن يتولاه مسلم، أو كتابي، يتولى ذبحه.","link":"https://binbaz.org.sa/fatwas/1416/حكم-اكل-اللحوم-المستوردة-من-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_360.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":6052,"question":"يسأل كذلك عن الدجاج المستورد من الخارج سيما أن اللحم غال الآن، وهم في حاجة لأكل الدجاج؟","title":"حكم اللحوم المستوردة بحسب بلادها","answer":"الجواب: اللحم الخارجي أقسام: ما كان من البلاد الشيوعية، والبلاد الوثنية، كالهندوس، والشيوعيين .. هذا لا يؤكل حتى نعلم أنه ذبحه مسلم، أو كتابي، أما ما ورد من بلاد النصارى، كالفرنسية والأمريكان، فالأصل فيه الحل، حتى نعلم أنه ذبح على غير الشرع، وأما إذا كنا لا نعلم؛ فالأصل في ذبائح أهل الكتاب هو الحل، هذا هو الأصل.","link":"https://binbaz.org.sa/fatwas/1466/حكم-اللحوم-المستوردة-بحسب-بلادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_396.mp3","categories":["قضايا معاصرة","الذكاة والصيد"]},{"id":7513,"question":"هذا سؤال من المرسل عزيز الغامدي يسأل عن الذبيحة يقول: السلام عليكم ورحمة الله وبركاته، وبعد: لقد حدث علي قصة وقصدي أستفسر من سماحتكم، ومشكلتي: أنا في ثلاثة عشر سنة من عمري وذبحت ذبيحة العيد أي: عيد النحر، وعندما قطعت الجلد فقط جاءتني حرمة وأكملت ما في هذه الذبيحة، أي: أنها قطعت البلعوم ومخته والرقبة، أي وتقول: ومخة الرقبة وذكتها، فما هو رأي سعادتكم أو سماحتكم هل ذبيحتي حلال؟ وتكملة هذه الأنثى ما يضر بصحة الحلال؟ نرجو إفادتنا عن ذلك وحفظكم الله.","title":"حكم تولي الصبي والمرأة الذبح","answer":"الجواب: لا حرج في تولي الصبي العاقل ابن سبع سنين فأكثر العاقل الذبح، ولا حرج تولي النساء الذبح، كل ذلك لا حرج فيه، المرأة تذبح مثل الرجل، والصبي كذلك العاقل يذبح مثل الكبير، لا حرج في ذلك، ذبيحة الصبي العاقل والمرأة كلها صحيحة وحلال إذا قطعت القطع الشرعي؛ قطعت الحلقوم والمري، أو كملت ذلك بقطع الودجين، كل ذلك قطع حسن، فالمقصود: أنه ليس في ذبيحة المرأة شيء ولا ذبيحة الصبي العاقل شيء. نعم.","link":"https://binbaz.org.sa/fatwas/4477/حكم-تولي-الصبي-والمراة-الذبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00813.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":7521,"question":"هذه رسالة من المستمع عادل ناصر الفصام يقول فيها: ما حكم أكل الدجاج الذي يأتينا من فرنسا، والذي نسمع أنه يذبح بالكهرباء، وما هو واجب وزارة التجارة منه، أفيدونا وفقكم الله؟","title":"حكم ذبائح أهل الكتاب","answer":"الجواب: هذا موضوع قد طرق غير مرة، قد تكلمنا فيه غير مرة، وقد تكلمنا مع وزارة التجارة في ذلك غير مرة، وجرى في ذلك مكاتبة بيننا وبينها، والمعلوم منها: أن كل ما يرد إلى هذه البلاد كله معروف حله، وأنه ليس فيه شك، وأنه من الأشياء الطيبة المعلومة من جهة الذبح ومن جهة غيره، والأصل أيضاً حل ما يأتي من بلاد أهل الكتاب، هذا هو الأصل، ما جاءنا من بلاد أهل الكتاب؛ من النصارى واليهود ، فالأصل حله؛ لأن الله سبحانه أباح لنا طعام أهل الكتاب، وطعامهم ذبائحهم، فالذي يأتي من فرنسا، أو من إنجلترا، أو من الدنمارك، أو ما أشبه ذلك من بلاد النصارى وهكذا بلاد اليهود -لو كان بيننا وبينهم صلة- فهو حل لنا؛ لأنه من طعامهم، وليس علينا أن نفتش ونقول: لعل كذا، لعل كذا، أما إذا علمنا أنه ذبح على غير الشريعة مثل الخنق والصعق بالكهرباء، ونحو ذلك، إذا علمنا هذا في هذه الذبيحة أو في هذا اللحم، لا نأكله، أما إذا لم نعلم فالأصل الحل مثل ذبائح المسلمين، الأصل فيها الحل حتى نعلم أن هذا مسلم ذبحها ذبحاً غير شرعي كالخنق، وبهذا نكون قد أخذنا بالرخصة والتيسير وتركنا الحرج والتكلف. نعم.","link":"https://binbaz.org.sa/fatwas/4495/حكم-ذباىح-اهل-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_009/00906.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":8186,"question":"ونبدأ برسالة المستمع، مستمع من ضواحي الخرج، يقول في رسالته المستمع -وقد كتب اسمه في.. لكنه غير واضح جداً- يقول: إنه من ضواحي مدينة الخرج، يقول في رسالته: هل لحوم الدجاج والأغنام المستوردة من الخارج حلال أم هي حرام، مع ذكر الدليل إن وجد وفقكم الله؟","title":"تفصيل الحكم في اللحوم المستوردة","answer":"الجواب: ... أما بعد: هذه اللحوم المستوردة فيها تفصيل: إن كانت من بلاد أهل الكتاب كـاليهود والنصارى فيحل لنا، مثل ما يستورد من فرنسا، إنجلترا، أمريكا، الدنمارك وأشباه ذلك؛ لأن الله أباح لنا طعام أهل الكتاب، حيث قال : وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ [المائدة:5]، وطعامهم ذبائحهم، الله أباح لنا طعامهم وهي ذبائحهم، وقد أجمع أهل العلم على ذلك، فما كان من بلاد أهل الكتاب وهم من اليهود والنصارى فهو حل لنا، إلا إذا علمنا أنه ذبح على غير الشرع، كأن يكون ذبح بالخنق والوقذ، هذا لا يحل، مثل ذبيحة المسلم التي يذبحها بالخنق والوقذ لا تحل، أما مادمنا نجهل ذلك فالأصل الحل، ما دمنا لا نعلم أنها ذبحت على غير الشرع، فالأصل حل ذلك، مثل ذبيحة المسلم، أما الذبائح الأخرى التي ترد من البلاد الشيوعية أو الوثنية كالهند، أو الشيوعية كبلغاريا والسوفيت هذه لا تحل، إلا إذا علمنا أنه ذبحها مسلم أو كتابي، إذا علمنا ذلك لا بأس، وأما إذا لم نعلم فالأصل تحريم ذبائحهم، ....... تحريم ذبائح الوثنيين وتحريم ذبائح الملحدين، ذبائح الملحدين من الشيوعيين ، فينبغي التفريق والتفصيل. نعم.","link":"https://binbaz.org.sa/fatwas/5995/تفصيل-الحكم-في-اللحوم-المستوردة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_092/09201.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":8314,"question":"أخت من جيزان اسمها دعاء جبريل -كما سمت نفسها- تسأل مجموعة من الأسئلة، خمسة أسئلة في الواقع.. سماحة الشيخ، في سؤال لها تقول: عندما تذبح ذبيحة لنا أحياناً يذبحها إنسان لا يصلي، ولكنه مسلم، وقد سمعت في هذا البرنامج أن الذي لا يصلي يعتبر كافر، فهل علي إثم إذا أكلت من لحم هذه الذبيحة، أفيدونا أفادكم الله؟","title":"هل تجوز ذبيحة تارك الصلاة؟","answer":"الجواب: اختلف العلماء رحمة الله عليهم في الرجل الذي يدع الصلاة وهو لا يجحدها، يعلم أنها فرض وأنها واجبة عليه، ولكنه يتساهل فيصلي تارة ويدع الصلاة أخرى، أو لا يصلي بالكلية؟\nفذهب جمع من أهل العلم إلى أنه قد أتى منكراً عظيماً أعظم من الزنا وأعظم من السرقة وأعظم من العقوق، لكنه لا يكفر كفراً أكبر بل كفر أصغر، هكذا قال جمع من أهل العلم، وبهذا قالوا: تحل ذبيحته؛ لأنه لا يزال مسلماً.\nوذهب آخرون من أهل العلم إلى أنه يكفر بذلك، متى ترك الصلاة عمداً ولو لم يجحد وجوبها فإنه يكفر بذلك، وهذا هو الصواب هذا هو الحق، وهذا هو المروي عن الصحابة ، قال عبد الله بن شقيق العقيلي التابعي الجليل: لم يكن أصحاب رسول الله ﷺ يرون شيئاً من الأعمال تركه كفر إلا الصلاة . فجعلوا ترك الصلاة كفراً، وإن لم يجحد وجوبها، وهكذا يقول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ويقول عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، والأحاديث الصحيحة في هذا كثيرة تدل على أن من تركها كفر وإن لم يجحد وجوبها، سواءً كان رجلاً أو امرأة.\nهذا هو الصواب وبهذا تكون ذبيحته غير حل، إذا ذبح ذبيحة تكون ذبيحته ميتة كذبيحة المجوسي وشبهه، ذبيحة اليهودي حل، ذبيحة النصراني حل؛ لأنه من أهل الكتاب، أما ذبيحة الكافر بترك الصلاة أو بعبادة الأموات والاستغاثة بالأموات أو بسب الدين أو بالاستهزاء بالدين هؤلاء كفار أشد من اليهود والنصارى ، تكون ذبيحتهم غير صحيحة وغير ذكية وغير مباحة.\nفينبغي الانتباه لهذا، والحذر من التساهل في هذا الأمر، أما من جحد وجوبها وقال: ما هي بواجبة، أو استهزأ بها فهذا كافر عند جميع أهل العلم، إذا جحد وجوبها واستهزأ بالمصلين ورأى أنهم ناقصو العقول بأداء هذه الصلاة، فهذا كفر أكبر نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/6119/هل-تجوز-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10809.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":8315,"question":"سماحة الشيخ! الذين يعملون في المجزرة لا يدرى عن أحوالهم، كيف يقول الشيخ للمستمعين لو تكرمتم؟","title":"ضرورة اعتناء المسئولين بالمجازر ومعرفة حال العاملين بها","answer":"الجواب: الواجب على المسئولين أن يعتنوا بهذا، وإذا كانوا لا يعلمون حالهم الذبيحة حلال؛ لأن ظاهرهم الإسلام، لكن على المسئولين عن المجازر أن يعنوا بالأمر، وأن لا يولوا إلا من عرف إسلامه، وأنه يصلي وأنه بعيد عن نواقض الإسلام، هذا هو الواجب على المسئولين. نعم.","link":"https://binbaz.org.sa/fatwas/6120/ضرورة-اعتناء-المسىولين-بالمجازر-ومعرفة-حال-العاملين-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10810.mp3","categories":["الذكاة والصيد"]},{"id":8316,"question":"والذي يذبح عليه أن يسأل الجزار أو لا يسأله، كيف يكون الحال سماحة الشيخ؟","title":"حكم سؤال الجزار عن دينه","answer":"الجواب: إن كان ظاهرهم الخير فلا حاجة إلى السؤال، وإن كانوا متهمين سألهم نعم.","link":"https://binbaz.org.sa/fatwas/6121/حكم-سوال-الجزار-عن-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10811.mp3","categories":["الذكاة والصيد"]},{"id":8589,"question":"وأولى رسائل هذه الحلقة وردتنا من السائل أنور صادق إسماعيل مصري الجنسية يقول الأخ أنور في رسالته: أخبر فضيلتكم أنني أعمل جزاراً وأرغب الاستفسار عن الذبح، هل يكفي فيه (باسم الله) وعدم الاتجاه إلى القبلة أم لابد من الاثنين معاً، حيث أن المحل الذي أعمل فيه ضيق ولا أستطيع الاتجاه إلى القبلة أثناء الذبح، أفيدوني أفادكم الله؟","title":"حكم التسمية واستقبال القبلة عند الذبح","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، وصلى الله وسلم على عبده ورسوله نبينا محمد وعلى آله وأصحابه أجمعين.\nأما بعد: فإن التسمية في الذبح واجبة مع الذكر؛ لأن الله جل وعلا أمر بها، وهكذا أمر بها رسوله عليه الصلاة والسلام، فلا يجوز تعمد ترك التسمية فيقول عند الذبح: باسم الله والله أكبر، هذه السنة ، باسم الله والله أكبر، فإن قال: باسم الله فقط كفى ذلك، وليس له تعمد ترك التسمية، فإن تركها نسياناً أو جهلاً فلا حرج في ذلك والذبيحة حلال، ولكن ليس له أن يدعها تعمداً، وأما استقبال القبلة فهو مستحب وليس بواجب، فلو ذبح إلى غير القبلة أجزأ ذلك وصح، لكن استقباله بالذبيحة القبلة يكون أفضل. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6662/حكم-التسمية-واستقبال-القبلة-عند-الذبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20901.mp3","categories":["الذكاة والصيد"]},{"id":8892,"question":"رسالتان سماحة الشيخ يسأل مرسلوها عن الذبح الشرعي، الأولى من الأخ حسن بن علي من البحرين، والثانية من السودان -كسلا، وباعثها أخونا سليمان مصدح ، ويسأل عن طريق الذبح الإبل خاصة، وعن التذكية الشرعية؟","title":"التذكية الشرعية","answer":"الجواب: التذكية الشرعية في الإبل والبقر والغنم أن يقطع الذابح الحلقوم والمريء والودجين وهما العرقان المحيطان بالعنق، أربعة أشياء، هذا هو المشروع الكامل، أكمل الذبح وأحسنه أن يقطع الحلقوم والمريء، الحلقوم مجرى النفس، والمريء مجرى الطعام والشراب، والودجين عرقان محيطان بالعنق، إذا قطعهما صار الدم أكثر خروجاً، فإذا قطع هذه الأربعة فالذبح حلال عند جميع العلماء.\nالحال الثاني: أن يقطع الحلقوم والمريء وأحد الودجين، وهذا أيضاً حلال صحيح وطيب وإن كان دون الأول.\nوالثالث: أن يقطع الحلقوم والمريء فقط دون الودجين وهو أيضاً صحيح وقال به جمع من أهل العلم، ويعمه قوله ﷺ: ما أنهر الدم وذكر اسم الله عليه فكل ليس السن والظفر.\nهذا هو المختار في هذه المسألة، وقال بعض أهل العلم: إن الذبح يحل بقطع الودجين فقط دون الحلقوم والمريء وفيه نظر، والأقرب والأظهر هو ما تقدم وهي ثلاث صفات:\nالصفة الأولى الكاملة: أن يقطع الأربعة.\nالثانية: وهي دونها ولكنها جيدة أن يقطع الحلقوم والمريء وأحد الودجين.\nالثالثة: أن يقتصر الحلقوم والمريء دون الودجين وهذه أيضاً ذبحة صحيحة وحاصل بها المقصود، أما الاقتصار على الودجين دون الحلقوم والمريء أو الودجين مع الحلقوم أو مع المريء ففيه نظر وخلاف لم يتضح لي وجه ذلك. نعم.\nالمقدم: بارك الله فيكم، هذا بالنسبة للغنم والبقر لكن ماذا عن الإبل؟\nالشيخ: والإبل كذلك، لكن الإبل يكون بالنحر يطعنها في الوهدة التي بين أصل العنق والصدر حتى يقطع الحلقوم والمريء والودجين جميعاً، وأما البقر والغنم يذبحها ذبحاً بالسكين ذبحاً دون طعن. نعم.\nالمقدم: بارك الله فيكم، هل هناك مكان محدد في الرقبة؟\nالشيخ: نعم، ما بين .. يعني الرقبة كلها محل ذبح.\nالمقدم: الرقبة كلها؟\nالشيخ: الرقبة كلها، نعم، أعلاها وأسفلها، لكن في الإبل في الوهدة في أسفل العنق بين الصدر وبين العنق، الوهدة المطمئنة. نعم.\nالمقدم: إذاً الذين يقولون: إن الذبح يجب أن يكون في أقرب منطقة إلى الرأس خاطئ؟\nالشيخ: لا ما هو بلازم، ليس بصحيح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7048/التذكية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_140/14005.mp3","categories":["الذكاة والصيد"]},{"id":8994,"question":"أخونا يسأل ويقول: ما حكم من ذبح وفصل نخاع عظم الرقبة قبل موت البهيمة؟ وهل عقر الإبل يكون من أسفل الرقبة وهي في حالة الوقوف؟","title":"حكم كسر عنق البهيمة عقب الذبح وقبل موتها","answer":"الجواب: الواجب أنه يذبح الذبح الشرعي ثم يترك الذبيحة لا ينخعها ولا يكسر عنقها، بل يكفي الذبح، متى قطع الحلقوم والمريء والودجين هذا هو الذبح الكامل، ولا ينبغي بل يكره له أن يخنعها إذ لا حاجة إلى هذا، نوع من التعذيب بلا حاجة، والعقر المعروف هو كونه يعقر البهيمة من جهة رجليها أو يديها، هذا العقر، وكان من سنة الجاهلية العقر عند القبور، والعقر للعظماء تكريمًا لهم وتعظيمًا لهم، فحرمه الإسلام وقال النبي ﷺ: لا عقر في الإسلام، أما الذبح في الحلق فهذا ما يسمى عقرًا يسمى ذبحًا ويسمى نحرًا، في الإبل يسمى نحرًا، وفي الغنم والبقر يسمى ذبحًا ولا مشاحة أن يسمى ذبحًا للإبل ونحرًا في البقر لا مشاحة، لكن لا يسمى عقرًا، العقر أن يعقرها في قوائمها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7152/حكم-كسر-عنق-البهيمة-عقب-الذبح-وقبل-موتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17605.mp3","categories":["الذكاة والصيد"]},{"id":9162,"question":"الرسالة الأولى وصلت إلى البرنامج من الأخ فخري عبدالوهاب آل جعفر من الجمهورية العراقية، محافظة الأنبار، يقول في رسالته وفي بدايتها: بسم الله الرحمن الرحيم، إن الله  قال في كتابه العزيز: بسم الله الرحمن الرحيم: \"طعامكم حل لهم وطعامهم حل لكم\" ولكن الذين يتخذون المسيح ابن الله وبقولهم: هو ثالث ثلاثة: الابن، والأب، وروح القدس، هل يؤكل ذبحهم أم لا؟ أفيدونا أفادكم الله؟","title":"حكم أكل لحوم أهل الكتاب الذين يقولون بالتثليث","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله، وأمينه على وحيه، وصفوته من خلقه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فالسائل لم يذكر الآية على لفظها، ولفظها يقول الله : الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ [المائدة:5]، فالله  أحل لنا معشر الأمة المحمدية الطيبات من المآكل والمشارب والملابس وغير ذلك، وأحل لنا طعام الذين أوتوا الكتاب، والذين أوتوا الكتاب هم اليهود والنصارى، يقال لهم: أهل الكتاب، فطعامهم حل لنا، والطعام هو الذبائح كما قال ابن عباس وغيره طعامهم ذبائحهم، فإذا ذبحوا إبلاً، أو بقراً، أو غنماً، أو غيرها مما أباح الله من الصيود والدجاج ونحو ذلك، فهو حل لنا، وطعامنا حل لهم، طعام المسلمين حل لهم أيضاً، وهذا كله إذا لم نعلم أنهم ذبحوه على غير الشرع، أما إذا علمنا أنهم أهلوه بغير الله، فهو حرام علينا؛ لأن الله حرم علينا ما أهل به لغير الله، إذا علمنا أن هذه الذبيحة ذبحوها للمسيح ، أو ذبحوها لأمه، أو ذبحوها لآلهتهم المعبودة من دون الله لم تحل لنا، وهكذا إذا علمنا أنهم خنقوها خنقاً، ما ذبحوها، خنقوها، فالمنخنقة محرمة علينا، وهكذا إذا علمنا أنهم ذبحوها على طريقة أخرى غير شرعية فلا تحل لنا، كالوقيذة التي يضربونها بالعمود أو بغيره، أو بالصرع الكهربائي، هذه لا تحل لنا.\nأما إذا كنا لا نعلم فذبيحتهم حل لنا، إذا جاءنا طعامهم من بلادهم أو جلبوه إلينا فإنا نشتريه ونأكله إلا إذا علمنا أنهم فعلوه على غير الطريقة الشرعية، يعني: ذبحوه على غير الطريقة الشرعية، وإلا فالأصل أنه حل لنا؛ لقول الله : وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ [المائدة:5] هذا هو المعتمد في هذه المسألة. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7319/حكم-اكل-لحوم-اهل-الكتاب-الذين-يقولون-بالتثليث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23201.mp3","categories":["الذكاة والصيد"]},{"id":9163,"question":"السؤال الثاني في رسالة الأخ (ن. أ. غ) بنجلاديشي مقيم في الإمارات العربية المتحدة يقول فيه: ما حكم أكل الدجاج والأبقار والأغنام المثلجة المستوردة من بلاد الكفار أفيدونا أفادكم الله؟","title":"حكم أكل اللحوم المستوردة من بلاد الكفار","answer":"الجواب: هذه اللحوم المثلجة من أبقار وأغنام وغيرها لا بأس أن تؤكل إذا كانت مستوردة من بلاد أهل الكتاب وهم اليهود والنصارى ؛ لأن الله أحل لنا ذبائحهم، فلا بأس أن نأكل ما يستورد منهم إلا إذا علمنا أنه ذبح على غير الشريعة، فإذا علمنا ذلك أن هذه الذبيحة ذبحت على غير الشريعة، أو أنها مستوردة من الشركة الفلانية التي تذبح على غير الشريعة بالصعق أو غيره من أنواع الخنق أو غير ذلك فلا نأكله، أما ما دمنا لا نعلم وقد استورد من بلاد فرنسا أو أمريكا أو انجلترا أو غيرها من دول النصارى فلا حرج علينا، وهكذا ما يكون من بلاد اليهود لو كان بيننا وبينهم اقتصاد فإنهم من أهل الكتاب قاتلهم الله وكفانا شرهم. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7314/حكم-اكل-اللحوم-المستوردة-من-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_231/23105.mp3","categories":["الذكاة والصيد"]},{"id":9522,"question":"هذا سؤال من المستمع محمد عبدالله من العراق يقول: إننا نعلم أن الله ذكر في كتابه العزيز: وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ [المائدة:5] ولكن هناك آية تذكر بأن أهل الكتاب قد كفروا وهذا الآية في بداية سورة محمد : الَّذِينَ كَفَرُوا وَصَدُّوا عَنْ سَبِيلِ اللَّهِ أَضَلَّ أَعْمَالَهُمْ ۝ وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَآمَنُوا بِمَا نُزِّلَ عَلَى مُحَمَّدٍ وَهُوَ الْحَقُّ مِنْ رَبِّهِمْ كَفَّرَ عَنْهُمْ سَيِّئَاتِهِمْ وَأَصْلَحَ بَالَهُمْ [محمد:1-2] يقول: فـاليهودية لم تؤمن بمحمد، وليس هذا فحسب بل إنهم كفروا برب العالمين عندما قالوا: يد الله مغلولة حيث لعنهم الله، أما النصارى فإنهم كفروا عندما قالوا: إن الله ثالث ثلاثة : لَقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ ثَالِثُ ثَلاثَةٍ وَمَا مِنْ إِلَهٍ إِلاَّ إِلَهٌ وَاحِدٌ [المائدة:73] وآية أخرى: لقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ هُوَ الْمَسِيحُ ابْنُ مَرْيَمَ [المائدة:17] إذاً فهم قد كفروا بالبداية بالله، ثم لم يؤمنوا بالنبي محمد ﷺ، فماذا عسانا أن نعمل حيث تردنا لحوم مذبوحة سواءً في بلاد أوروبية أو اشتراكية وأكثرهم يقتل هذه الحيوانات بواسطة الصعق الكهربائي، وذلك لما أوضحته إحدى المجلات التي تصدر في بعض الدول الإسلامية، وهل يكون المرء آثماً لو أكل من هذه اللحوم، أم أنه يترك الشك ويعتمد على الآية الكريمة : وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ [المائدة:5].","title":"حكم أكل ذبائح أهل الكتاب","answer":"الجواب: أهل الكتاب هم اليهود والنصارى، والذي أباح طعامهم هو الذي قال فيهم ما ذكرته من الآيات في تكفيرهم تكفير اليهود قولهم: يد الله مغلولة قولههم: إِنَّ اللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ [آل عمران:181]، كذلك هو الذي كفر النصارى في قوله سبحانه: لَقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ هُوَ الْمَسِيحُ ابْنُ مَرْيَمَ [المائدة:17] وكفرهم بقولهم: إِنَّ اللَّهَ ثَالِثُ ثَلاثَةٍ [المائدة:73] فهو سبحانه كفرهم وأبان ضلالهم، ومع ذلك أباح لنا طعامهم، فهم كفار ومشركون وظلمة ومفسدون، ولكن الله سبحانه لطف بنا وأباح لنا طعامهم فضلاً منه وإحساناً، وطعامهم ذبائحهم كما قاله ابن عباس وغيره، فإذا علمنا أن هذه الذبائح من ذبائح أهل الكتاب فهي حل لنا سواء كانت من أوروبا أو من أمريكا أو من غير ذلك.\nفالحاصل أن طعام أهل الكتاب وهم اليهود والنصارى سواءً كانوا ذميين أو حربيين حل لنا بنص القرآن، إلا إذا علمنا أن هذه الذبيحة أهلت لغير الله ذبحوها لآلهتهم، إذا علمنا ذلك حرم علينا وهكذا إذا علمنا أنهم ذبحوها بالخنق أو بالصعق الكهربائي يقيناً أن هذه الذبيحة المعينة التي جاءت في هذه العلبة أو في هذا الإناء، إذا علمنا هذا حرمت علينا و إلا فالأصل حل ذلك وعلينا أن نقبل رخصة الله سبحانه.\nأما ما يتعلق ببعض الشركات فليس علينا أن نتبع ذلك، إذا علمنا أن هذه الذبيحة أهلت لغير الله أو ذبحت على غير شرع الله تركناها، و إلا فالأصل أن ذبائحهم حل لنا بنص القرآن الكريم وهم مع هذا كفار، لكن الله استثنى ذبائحهم دون غيرهم.\nأما الوثنيون من المجوس وهكذا الشيوعيون كلهم ذبائحهم محرمة، كـالمجوس والبوذيون وسائر الكفرة من الشيوعيين وغيرهم ذبائحهم كلها محرمة، فما يذبح في بلغاريا أو الصين الشعبية أو أشباه ذلك من الدول الشيوعية هذا لا يحل لنا، إلا إذا علمنا أنه تولاه مسلم أو تولاه كتابي، وإن كان في بلاد الشيوعيين إذا تولاه كتابي أو تولاه مسلم حلت تلك الذبيحة، وإلا فالأصل أن ما يرد من البلدان الشيوعية من بلغاريا أو رومانيا أو الصين الشعبية أو غير ذلك هذا نتركه لا يحل لنا ولا نستعمله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7685/حكم-اكل-ذباىح-اهل-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_244/24404.mp3","categories":["الذكاة والصيد"]},{"id":9556,"question":"هذه رسالة وردت من الجمهورية العراقية من عبدالكريم الكاظمي يقول فيها: سمعت في إحدى حلقات برنامج نور على الدرب سؤالاً عن حكم ذبائح أهل الكتاب وهل يجوز أكلها، فكان جواب الشيخ الفاضل: ذبائح أهل الكتاب ذبائح شرعية يجوز أكلها؛ لأن كتبهم تقول بعدم جواز الذبح لغير الله تعالى، يقول السائل: ونحن نعلم ما عليه أجمع العلماء من شروط الذبيحة الشرعية من الاتجاه للقبلة، وأن يكون الذابح مسلم والتسمية.. إلى آخره، وهذه الأشياء كما تعلمون غير موجودة عند أهل الكتاب، فكيف تكون ذبائح أهل الكتاب شرعية يجوز أكلها؟ أفيدونا أفادكم الله.","title":"الأصل في ذبائح أهل الكتاب الإباحة","answer":"الجواب: أولاً: ذبائح أهل الكتاب حل بكتابنا ما هو من أجل كتبهم، الله أباح لنا ذبائح أهل الكتاب في كتابه العظيم في سورة المائدة، حيث قال : الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ [المائدة:5] فالله أباح لنا طعامهم، وطعامهم هو الذبائح كما قال ابن عباس وغيره، فذبائحهم لنا حل إذا لم نعلم أنها ذبحت على غير الشرع، فالأصل الإباحة هذا هو الأصل كذبيحة المسلم إلا إذا علمنا أنه ذبحها بالخنق أو بضرب الرأس فهذا يحرمها علينا، وما دمنا لا نعلم أنه ذبحها على غير الشرع فالأصل إباحتها لنا ..... هم اليهود والنصارى ، وليس من شرط الذبيحة التوجيه إلى القبلة إنما هذا مستحب، لو ذبحها إلى غير القبلة فلا حرج، التوجيه إلى القبلة مستحب فقط، والتسمية مأمور بها فإذا تركها جاهلاً أو ناسياً لم تحرم الذبيحة، لكن يجب أن يسمي إذا ذكر أما إن كان ناسياً أو جاهلاً فالذبيحة حلال، وليس من شرط الذبيحة أن يذبحها المسلم لو ذبحها الكتابي حلت، هذه الشروط التي قلتها ليست على ظاهرها، فليس من شرط الحل التوجيه إلى القبلة بل هذا مستحب، وليس من شرط الحل أن يذبحها مسلم، لا، لو ذبحها كتابي جاز، وليس من شرطها التسمية في كل الأحوال، التسمية مع الذكر أما مع الجهل أو مع النسيان فتحل؛ لأن الله سبحانه يقول: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] وصح عن رسول الله ﷺ أنه قال: قال الله: قد فعلت يعني: قبل الدعاء، وفي الحديث: عفي لأمتي عن الخطأ والنسيان وما استكرهوا عليه فإذا ترك الإنسان التسمية ناسيًا أو جاهلًا ما عرف الحكم الشرعي حلت.\nفينبغي للسائل التنبه لهذا وألا يقول إلا عن علم، ينبغي للسائل وغيره ألا يقول إلا عن علم؛ لأن الله يقول سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] يعني: على علم، ولأن القول على الله بغير علم أمر منكر وفي مرتبة فوق الشرك نسأل الله السلامة، قال الله تعالى: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] فجعل القول عليه بغير علم فوق الشرك؛ لأن القول عليه بغير علم فيه خطر عظيم، ومنه الشرك فإن المشرك قد قال على الله بغير علم، وقال تعالى: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا وَلا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:168-169] فالشيطان يأمر بالسوء والفحشاء، ويأمرنا أن نقول على الله بغير علم.\nفالواجب على المنتسب للدين من العلماء وطلبة العلم وغيرهم الواجب التثبت في الأمور، وألا يقول الإنسان إلا عن علم، لا يتكلم إلا عن علم ولا يفتي إلا عن علم. رزق الله الجميع التوفيق والهداية والسداد. نعم.\nالمقدم: أثابكم الله وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7721/الاصل-في-ذباىح-اهل-الكتاب-الاباحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27005.mp3","categories":["الذكاة والصيد"]},{"id":10082,"question":"يقول: هل على الإنسان إثم في قتل الحيوانات البرية الأليفة منها وغير الأليفة، إذ أني أرى بعض الناس ليس له عمل إلا صيد الحيوانات، وهو ليس جائع ويصطاد الثعالب والأرانب والضباع والذياب والوبار والغزلان والطيور بشتى أنواعها، كيف ذلك والدين الإسلامي أمر بالرفق بالحيوان؟","title":"حكم قتل الحيوانات لمجرد العبث","answer":"الجواب: إذا كان لمصلحة شرعية ليأكل أو يبيع كأن يصيد الحبارى والظباء والأرانب، وغير هذا من الأشياء المباحة ليأكلها أو ليبيعها فلا بأس، أما إذا كان يصيدها ليقتلها ويتركها هذا لا ينبغي، أقل أحواله الكراهة الشديدة، فلا يصيد حيواناً مأكولاً إلا لمصلحة إما ليأكل أو يطعمه الفقراء أو يهديه أو يبيعه أما اللعب فلا يجوز، هذا لعب لا ينبغي للمؤمن أن يفعله، وقد روي عن النبي ﷺ أنه نهى عن الصيد إلا لمأكلة. يعني: إلا ليؤكل وينتفع به، أما الحيوانات الأخرى المحرمة فإن كانت تؤذي الناس فهو مأجور في قتلها، وأما إذا كانت لا تؤذي الناس فلا يشرع له تتبعها وهي لا تؤذي أحداً، سواء كان ثعلباً أو غيره، أما إذا كان قد آذى الناس فإنه يقتل كالثعلب الذي يصيد دجاجهم أو حمامهم، أو الذئب الذي يأكل غنمهم يقتل، أما أن يتتبع سباعاً لا تؤذي أحداً ولا تضر أحداً فلا ينبغي ذلك؛ لعدم الفائدة وعدم المصلحة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8249/حكم-قتل-الحيوانات-لمجرد-العبث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30412.mp3","categories":["أحكام الحيوان","الذكاة والصيد"]},{"id":10107,"question":"مستمع رمز إلى اسمه بالحروف (ع. س) يسأل ويقول: ما حكم الذبح في يوم العيد سواءً في عيد الفطر أو في الأضحى وتسمى العيدية؟ جزاكم الله خيرًا.","title":"حكم ذبيحة (العيدية)","answer":"الجواب: لا حرج في ذلك، إذا ذبح ليأكل إخوانه وأهل بيته في عيد الفطر أو عيد الأضحى، كل ذلك لا حرج فيه، وفي عيد الأضحى إذا جعله ضحية وأكلوا وأطعموا كله طيب، والحمد لله، نعم.\nالمقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8278/حكم-ذبيحة-العيدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27704.mp3","categories":["الذكاة والصيد"]},{"id":10319,"question":"ما حكم أكل ذبيحة من لا يصلي أو الذي نشك هل يصلي أم لا؟ وكيف نتصرف معهم إذا دعينا إلى ذبائحهم أكثر من مرة؟","title":"حكم أكل ذبيحة من لا يصلي","answer":"الجواب: من يدعي الإسلام تؤكل ذبيحته، من هو معروف بالإسلام ويتسمى بالإسلام وينسب إلى الإسلام ما عرف عنه مكفر تؤكل ذبيحته، أما من عرف أنه لا يصلي فلا تؤكل ذبيحته ولا تجاب دعوته بل يهجر حتى يتوب إلى الله عز وجل، وإذا كنت تشك فالأصل أنه يصلي، هذا هو الأصل في المسلم، فذبيحته حلال ما دمت تشك في ذلك، أما إذا علمت يقيناً أنه لا يصلي فإنه يستحق الهجر، ولا تؤكل ذبيحته، ولا تجاب دعوته، بل يجب على ولي الأمر أن يستتيبه فإن تاب وإلا قتل كافراً نسأل الله العافية، إذا رفع الأمر إلى ولي الأمر أو إلى المحكمة يجب أن يستتاب، فإن تاب وصلى وإلا وجب قتله مرتداً نسأل الله العافية؛ لقول الله جل وعلا: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]، فدل على أن من لم يتب من الشرك لا يخلى سبيله، وهكذا من لم يتب من ترك الصلاة لا يخلى سبيله، وهكذا من ترك الزكاة لا يخلى سبيله بل يطالب، لكن من ترك الصلاة يقتل كافراً، أما من ترك الزكاة يطالب يجبر بإخراج الزكاة ولا يكفر بذلك لأدلة أخرى.\nوهكذا من استمر على الشرك يستتاب فإن تاب وإلا قتل مرتداً نسأل الله العافية، ولما ارتد العرب في عهد الصديق  قاتلهم حتى رجع من رجع إلى الإسلام وحتى قتل من قتل على الردة، فالمرتد الذي يترك الإسلام يترك توحيد الله أو الإيمان بالرسول ﷺ أو يترك الصلاة يستتاب فإن تاب وإلا قتل كافراً.\nأما من ترك الزكاة فإن قاتل دونها يقاتل أيضاً ويكون كافراً إذا قاتل دونها، فإن قتاله دون الزكاة دليل على كفره وإنكاره وجوبها، أما إذا لم يسلمها ولكن ما جحد وجوبها ولا قاتل دونها فإنه يجبر عليها تؤخذ منه ويجبر عليها ويكون عاصياً بذلك، وأمره إلى الله جل وعلا إن مات على ذلك فأمره إلى الله وإن تاب تاب الله عليه؛ لأنه صح عن النبي ﷺ أنه قال: يوم القيامة يؤتى بالرجل الذي لا يؤدي الزكاة فيعذب بماله الذي تركه لم يؤد زكاته ويعذب بإبله وبقره وغنمه التي لم يزكها، ثم يرى سبيله بعد هذا إما إلى الجنة وإما إلى النار، فدل على أنه لا يكفر بذلك، إذا كان ما جحد وجوبها بل هو معرض لدخول النار، لكن من قاتل دونها فقد قاتلهم الصحابة، الصديق والصحابة قاتلوهم قتال المرتدين؛ لأن قتالهم دون الزكاة دليل على إنكارهم لها وإنكارهم لوجوبها، ولهذا عوملوا معاملة الكفار، نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/8500/حكم-اكل-ذبيحة-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31413.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":10439,"question":"ينتقل إلى مواضيع أخرى فيسأل ويقول: هل يجوز أكل ذبيحة تارك الصلاة؟","title":"حكم أكل ذبيحة تارك الصلاة","answer":"الجواب: ذبيحة تارك الصلاة من كفره حرم ذبيحته، ومن قال: إنه كفر دون كفر لم يحرم ذبيحته، والعلماء اختلفوا في ذلك في حق من ترك الصلاة ولم يجحد وجوبها ولكن تكاسل، فذهب جمع من أهل العلم إلى أنه يكفر بذلك كفراً أكبر، وهذا هو الأرجح والأقرب للدليل؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.","link":"https://binbaz.org.sa/fatwas/8612/حكم-اكل-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31804.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":10441,"question":"هل يجوز أكل ذبيحة أصحاب العقائد الشركية كالنذر والذبح والدعاء لمن يسمونهم أولياء بزعمهم؟ مع العلم أن هؤلاء لم تقم عليهم الحجة الكافية التي تزيل معها ما لديهم من شبهات؟","title":"حكم أكل ذبائح أصحاب العقائد الشركية","answer":"الجواب: من عرف بالعقيدة الفاسدة الشركية لا تؤكل ذبيحته، إذا كان بين مسلمين فلا عذر له؛ لأنه لم يسأل ولم يبال، فإذا عرف أنه يعبد غير الله ممن يسمونهم بالأولياء كعباد البدوي وعباد الحسين وعباد الحسن وعباد علي ، وكعباد ابن عربي وعباد غيرهم ممن يسمونهم بالأولياء هؤلاء كفار لا تؤكل ذبيحتهم، وهكذا غيرهم ممن يعبد غير الله، ينذر له، يذبح له، يستغيث به؛ لأن هذا الشرك الأكبر، هذا عمل الجاهلية، هذا عمل قريش وأشباههم مع هبل ومع اللات والعزى، وهذا عمل قوم نوح مع ود وسواع وأشباهه، ومثل هؤلاء يعتبرون فيمن قامت عليه الحجة؛ لأنهم بين المسلمين قد بلغهم القرآن وبلغتهم السنة وبلغهم كلام العلماء، ومن لم يبلغه شيء من ذلك فإنه معرض لا يبالي ولا يسأل، أما من كان في بلاد بعيدة عن المسلمين من أهل الفترة الذين لم تبلغهم الدعوة ولم يسمعوا بقول الله ولا رسوله، هذا له حكم الكفرة في الحكم الدنيوي وأمره إلى الله في الآخرة، في الحكم الدنيوي لا تؤكل ذبيحته مادام يعمل عمل الكفار، ولكن أمره إلى الله يوم القيامة، يمتحن يوم القيامة فإن أجاب الأوامر دخل الجنة وإن عصى دخل النار، هذا هو الصحيح في أهل الفترة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8613/حكم-اكل-ذباىح-اصحاب-العقاىد-الشركية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31805.mp3","categories":["الذكاة والصيد"]},{"id":10444,"question":"ينتقل إلى مواضيع أخرى فيسأل ويقول: هل يجوز أكل ذبيحة تارك الصلاة؟","title":"حكم أكل ذبيحة تارك الصلاة","answer":"الجواب: ذبيحة تارك الصلاة من كفره حرم ذبيحته، ومن قال: إنه كفر دون كفر لم يحرم ذبيحته، والعلماء اختلفوا في ذلك في حق من ترك الصلاة ولم يجحد وجوبها ولكن تكاسل، فذهب جمع من أهل العلم إلى أنه يكفر بذلك كفراً أكبر، وهذا هو الأرجح والأقرب للدليل؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.","link":"https://binbaz.org.sa/fatwas/8612/حكم-اكل-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31804.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":10538,"question":"السائل: أسامة عبدالله من الدمام يقول في هذا  ما هي شروط الذكاة؟ وهل لذبح الأغنام موضع معين في الرقبة أو الحلقوم؟","title":"شروط الذبح ومواضعه","answer":"الجواب: نعم، شروط الذبح معروفة، لا بد أن يكون الذبح في محل الذبح، وأن ...... آلة الذبح حتى ينهي الذبح. في الإبل في اللبة يطعنها في اللبة حتى تنتهي حتى تموت، والبقرة والغنم على جنبها الأيسر الأفضل تذبح على جنبها في الحلقوم أو في المريء، وإذا قطع الودجين فهو الأكمل، الودجين: العرقان المتصلان بالحلقوم والمريء، لا بد من هذا وهذا، ولكن الحلقوم والمريء يجزي في الذبح، وإذا قطع مع الحلقوم أحد الودجين أو كليهما يكون أكمل وأفضل، ولا بد أن يراعي في ذلك أن تكون الآلة جيدة، وأن لا يعذب الحيوان يذبح في محل الذبح لا في غيره، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8713/شروط-الذبح-ومواضعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28410.mp3","categories":["الذكاة والصيد"]},{"id":10542,"question":"يقول: أرجو من سماحة الشيخ أن يفتوني في فريسة كلب الصيد أو الصقر المدرب، إن كانت حية أو ميتة بعد صيدها جزاكم الله خيرًا؟","title":"حكم أكل ما صاده الكلب أو الصقر المدربين","answer":"الجواب: إذا قتله الكلب المعلم حل، قال .. النبي ﷺ: وإن وجدته قتيلًا فكل المقصود أنه إذا قتله الكلب، أو قتله الصقر بأن أرسل الصقر أو الكلب فقتل الصيد حل، الحمد لله، إلا أن يأكل منه، إذا أكل منه لا تأكله؛ يقول النبي ﷺ: إذا أكل فلا تأكل فإنما صاد لنفسه أما إذا قتله ولم يأكل فهو حل لنا حل للمصيد له، نعم.","link":"https://binbaz.org.sa/fatwas/8717/حكم-اكل-ما-صاده-الكلب-او-الصقر-المدربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28414.mp3","categories":["الذكاة والصيد"]},{"id":11009,"question":"من ذبح ذبيحة وهو في سن الحادية عشرة هل تؤكل ذبيحته وإن لم يكن يحافظ على الصلاة؟","title":"حكم ذبيحة الإنسان غير الراشد","answer":"الجواب:  إذا كان مسلمًا تؤكل ذبيحته؛ لأن الصغير لا تجب عليه الصلاة ما دام مسلمًا يشهد أن لا إله إلا الله، وأن محمدًا رسول الله يعني: تبع المسلمين، تبع والديه محكومًا بإسلامه، فذبيحته حلال؛ لأن الصلاة في حقه غير واجبة حتى يبلغ، أما الذي قد بلغ وهو لا يصلي فلا تجوز ذبيحته في أصح قولي العلماء؛ لأن ترك الصلاة عمدًا كفر، نسأل الله العافية، في حق المكلف، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9197/حكم-ذبيحة-الانسان-غير-الراشد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36613.mp3","categories":["الذكاة والصيد"]},{"id":11016,"question":"من ذبح ذبيحة وهو في سن الحادية عشرة هل تؤكل ذبيحته وإن لم يكن يحافظ على الصلاة؟","title":"حكم ذبيحة الإنسان غير الراشد","answer":"الجواب:  إذا كان مسلمًا تؤكل ذبيحته؛ لأن الصغير لا تجب عليه الصلاة ما دام مسلمًا يشهد أن لا إله إلا الله، وأن محمدًا رسول الله يعني: تبع المسلمين، تبع والديه محكومًا بإسلامه، فذبيحته حلال؛ لأن الصلاة في حقه غير واجبة حتى يبلغ، أما الذي قد بلغ وهو لا يصلي فلا تجوز ذبيحته في أصح قولي العلماء؛ لأن ترك الصلاة عمدًا كفر، نسأل الله العافية، في حق المكلف، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9197/حكم-ذبيحة-الانسان-غير-الراشد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36613.mp3","categories":["الذكاة والصيد"]},{"id":11249,"question":"تسأل تقول: إن لوالدتنا أقارب يتقربون إلى ذوي القبور وتأكل من ذبائحهم، وطلبنا منها أن تتبرأ منهم لكنها لم تستجب فما هو توجيه سماحتكم جزاكم الله خيرًا؟","title":"حكم أكل ذبيحة من يتقرب إلى أصحاب القبور","answer":"الجواب:  الذين يتقربون إلى أصحاب القبور بالدعاء أو الاستغاثة أو الذبائح مشركون لا تؤكل ذبيحتهم، فالواجب ترك ذبيحتهم والإنكار عليهم، ودعوتهم إلى الله، وتوجيههم إلى الخير لعلهم يهتدون، الله سبحانه وتعالى حرم ذبيحة الكافر، إلا أهل الكتاب وهم اليهود والنصارى إذا ذبحوها لغير آلهتم إذا ذبحوها للحم وذكروا اسم الله عليها. أما عباد القبور ودعاة الأموات والمستغيثون بالأموات هؤلاء ذبيحتهم حرام، فالواجب الحذر من أكلها مع دعوتهم إلى الله، وإرشادهم وتعليمهم، لعل الله يهديهم بأسبابكم. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم تسأل عن علاقة والدتها بأولئك الذين يتقربون للموتى، وبوالدهم الذي ذكرت صفته، ثم تقول: هل يؤثر ذلك على معتقدها؟ الشيخ: على كل حال الواجب عليها الإنكار والتعليم، ولا يضرها إذا أنكرت عليهم وعلمتهم فقد أدت ما عليها، والحمد لله. المقدم: أما الوالدة فكيف يكون معتقدها؟ الشيخ: عليها تعليمها وإرشادها وتعليم الوالد والاستعانة بأهل الخير، الذين عندهم علم، حتى يساعدوها في دعوته إلى الله والإحسان إليهم، الله قال جل وعلا في حق ولد الكافرين قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]، فعليها أن تحسن إليهما وأن ترفق بهما، وأن تخاطبهما بالتي هي أحسن، مع الجد في دعوتهما إلى الخير، والاستعانة بالناس الطيبين في دعوة والديها إلى الخير، من العلماء والأخيار، لعلهما يهتديان. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم إذا كان والدها متوفيًا فكيف يكون تصرفهم حينئذٍ؟ الشيخ: لا يدعون له ولا يستغفرون له، إذا مات على الكفر لا يدعى له ولا يستغفر له؛ لأنه مات على الكفر، قال الله تعالى: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى [التوبة:113].  فالمقصود أنهم لا يستغفرون لهم، ولا يدعون لهم، ولا يتصدقون عنهم، ما داموا ماتوا على عبادة القبور والاستغاثة بالأموات ونحو ذلك، نسأل الله العافية. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9440/حكم-اكل-ذبيحة-من-يتقرب-الى-اصحاب-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37413.mp3","categories":["الذكاة والصيد"]},{"id":11261,"question":"تسأل تقول: إن لوالدتنا أقارب يتقربون إلى ذوي القبور وتأكل من ذبائحهم، وطلبنا منها أن تتبرأ منهم لكنها لم تستجب فما هو توجيه سماحتكم جزاكم الله خيرًا؟","title":"حكم أكل ذبيحة من يتقرب إلى أصحاب القبور","answer":"الجواب:  الذين يتقربون إلى أصحاب القبور بالدعاء أو الاستغاثة أو الذبائح مشركون لا تؤكل ذبيحتهم، فالواجب ترك ذبيحتهم والإنكار عليهم، ودعوتهم إلى الله، وتوجيههم إلى الخير لعلهم يهتدون، الله سبحانه وتعالى حرم ذبيحة الكافر، إلا أهل الكتاب وهم اليهود والنصارى إذا ذبحوها لغير آلهتم إذا ذبحوها للحم وذكروا اسم الله عليها. أما عباد القبور ودعاة الأموات والمستغيثون بالأموات هؤلاء ذبيحتهم حرام، فالواجب الحذر من أكلها مع دعوتهم إلى الله، وإرشادهم وتعليمهم، لعل الله يهديهم بأسبابكم. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم تسأل عن علاقة والدتها بأولئك الذين يتقربون للموتى، وبوالدهم الذي ذكرت صفته، ثم تقول: هل يؤثر ذلك على معتقدها؟ الشيخ: على كل حال الواجب عليها الإنكار والتعليم، ولا يضرها إذا أنكرت عليهم وعلمتهم فقد أدت ما عليها، والحمد لله. المقدم: أما الوالدة فكيف يكون معتقدها؟ الشيخ: عليها تعليمها وإرشادها وتعليم الوالد والاستعانة بأهل الخير، الذين عندهم علم، حتى يساعدوها في دعوته إلى الله والإحسان إليهم، الله قال جل وعلا في حق ولد الكافرين قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]، فعليها أن تحسن إليهما وأن ترفق بهما، وأن تخاطبهما بالتي هي أحسن، مع الجد في دعوتهما إلى الخير، والاستعانة بالناس الطيبين في دعوة والديها إلى الخير، من العلماء والأخيار، لعلهما يهتديان. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم إذا كان والدها متوفيًا فكيف يكون تصرفهم حينئذٍ؟ الشيخ: لا يدعون له ولا يستغفرون له، إذا مات على الكفر لا يدعى له ولا يستغفر له؛ لأنه مات على الكفر، قال الله تعالى: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى [التوبة:113].  فالمقصود أنهم لا يستغفرون لهم، ولا يدعون لهم، ولا يتصدقون عنهم، ما داموا ماتوا على عبادة القبور والاستغاثة بالأموات ونحو ذلك، نسأل الله العافية. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9440/حكم-اكل-ذبيحة-من-يتقرب-الى-اصحاب-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37413.mp3","categories":["الذكاة والصيد"]},{"id":11848,"question":"يسأل ويقول: هل يجوز للمرأة أن تذبح الذبيحة؟","title":"ذبيحة المرأة تجوز لمن تحسن ذلك","answer":"الجواب:  نعم، لا بأس، النبي أقر المرأة في ذبح الذبيحة إذا ذبحت ... تحسن الذبيحة، وذبحت لا بأس، .. الضحية، وغير الضحية. نعم. المقدم: نعم نعم.","link":"https://binbaz.org.sa/fatwas/10030/ذبيحة-المراة-تجوز-لمن-تحسن-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39610.mp3","categories":["الذكاة والصيد"]},{"id":11942,"question":"بعد هذا رسالة وصلت إلى البرنامج من القاهرة العريش، وباعثها مستمع يقول: السيد بن محمود الجندي، له عدد من الأسئلة في أحدها يقول: هل يجوز صيد الطيور البرية من الحمام واليمام والعصافير بواسطة بندقية ضغط الهواء أو الأسلحة النارية؟ علمًا بأنني عند إطلاق النار عليها أقول: باسم الله، والله أكبر، أفيدوني جزاكم الله خيرًا.","title":"حكم صيد الحمام والعصافير بالسلاح الناري","answer":"الجواب:  لا مانع من صيد الطيور المباحة من الحمام والعصافير وغيرها بالأسلحة النارية، لا مانع من ذلك والحمد لله، فإن أدركته حيًا؛ فاذبحه، وإن أدركته قد مات؛ فهو حل لك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10127/حكم-صيد-الحمام-والعصافير-بالسلاح-الناري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42806.mp3","categories":["الذكاة والصيد"]},{"id":12642,"question":"يقول: إننا نقيم في وسط مجموعة من النصارى، ونأكل من ذبائحهم، وقد سمعناهم إذا بدؤوا الذبح يقولون: باسم الأب والابن، فهل يجوز أن نأكل من تلك الذبائح؟","title":"حكم ذبيحة النصارى الذين يذبحونها باسم الأب والابن","answer":"الجواب:  ما دام سموا عليها باسم الابن ما يصلح؛ لأن هذا شرك -والعياذ بالله- والمعنى سموا عليها غير الله -جل وعلا- فلا يأكلوا منها. أما إذا لم تعلموا فلكم الأكل منها؛ لأن الله أباح ذبيحة أهل الكتاب وهم اليهود والنصارى، وإذا لم تعلموا كيف ذبحوها فلكم الأكل، أما إذا علمتم أنهم سموا عليها باسم عيسى، باسم الابن وهو عيسى، أو سموا عليها باسم مريم، أو باسم أي صنم، أو أي معبود من دون الله؛ تحرم، وهكذا لو ذبحوها على غير الذبح الشرعي؛ تحرم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10852/حكم-ذبيحة-النصارى-الذين-يذبحونها-باسم-الاب-والابن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45712.mp3","categories":["الذكاة والصيد"]},{"id":12659,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول جهاد جميل الصرعاوي يسأل عددًا من الأسئلة من بينها هذا السؤال يقول فيه: صار هناك خلاف بيننا في مسألة ما إذا أراد إنسان أن يذبح شاة، هل يقول: باسم الله، أو لا؟ ومن لم يقل هل تكون ذبيحته مباحة؟","title":"حكم أكل الذبيحة التي لم يذكر اسم الله عليها","answer":"الجواب:  الواجب أن يسمي؛ لأن الله أمر بالتسمية، فالواجب أن يسمي الله عند الذبح يقول: بسم الله الرحمن الرحيم، أو باسم الله، ويكفي، وإذا تعمد تركها وهو يعلم الحكم الشرعي، لم تحل الذبيحة، لكن إذا تركها ناسيًا، أو جاهلًا، فالذبيحة حلال، أما إن تركها عامدًا وهو يعلم الحكم الشرعي، فالذبيحة لا تحل في أصح قولي العلماء؛ لأن الرسول ﷺ أمر من أراد الذبح، أو الصيد أن يسمي الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10869/حكم-اكل-الذبيحة-التي-لم-يذكر-اسم-الله-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45811.mp3","categories":["الذكاة والصيد"]},{"id":12867,"question":"من لبنان المستمع: حسن السنبيط -فيما يبدو- بعث برسالة ضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: هل يجوز للمرأة أن تذبح الذبيحة، سواء كانت من الأغنام، أو من الحمام، والدجاج، وما أشبه ذلك؟","title":"هل يجوز للمرأة أن تذبح الأغنام، والدجاج؟","answer":"الجواب:  نعم لا بأس بذلك، إذا كانت تحسن ذلك؛ فلا بأس، فقد أقر النبي ﷺ المرأة على ذبح الحيوان، فالمرأة في هذا كالرجل، إذا عرفت كيف تذبح؛ فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11082/هل-يجوز-للمراة-ان-تذبح-الاغنام-والدجاج ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46517.mp3","categories":["الذكاة والصيد"]},{"id":13065,"question":"على بركة الله نبدأ هذا اللقاء بسؤال لأحد الإخوة من السودان، يقول في هذا  ما حكم الأكل مع غير المسلمين، وما حكم أكل اللحوم المستوردة وهي ما أُهلَّ لغير الله به عند ذبحها؟ فنرجو من سماحة الشيخ إجابة.","title":"حكم الأكل مع غير المسلمين وأكل ما أهل لغير الله","answer":"الجواب:  باسم الله، والحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالأكل مع غير المسلمين إذا دعت إليه الحاجة لا بأس كالضيوف، أو يمر على جماعة، فيدعونه ويأكل معهم، فقد أكل النبي ﷺ مع اليهود طعام أهل الكتاب؛ فلا حرج، لكن لا يتخذهم أصحابًا ولا عشراء، إنما للحاجة، للعارض، كأن يكونوا ضيوفًا عنده، أو يمر عليهم لحاجة، فيأكل معهم، لا بأس إذا كان الطعام لا حرج فيه، مثل طعام أهل الكتاب، أو طعامًا لا يعلم فيه مانعًا من فاكهة أو خبز، ليس فيه ما يمنع الأكل. أما إذا كان طعامًا فيه لحم مما أهل به لغير الله؛ فلا يجوز، كذبائح المشركين الوثنيين، أو ذبيحة يعرف أن أهل الكتاب أهلوا بها لغير الله لا يجوز، إذا عرف أن اللحم هذا مهل به لغير الله؛ لا يأكل منه، أما إذا لم يعلم فالأصل العافية، الأصل السلامة في طعام أهل الكتاب. أما ذبائح المشركين فلا يأكل منها مثل: عباد الأوثان، عباد البدوي، عباد الحسين، عباد عبدالقادر الجيلاني، عباد الأصنام، عباد الجن، هذه لا يؤكل طعامهم، يعني: ذبائحهم، إنما هو خاص بأهل الكتاب من اليهود والنصارى التي لا يعرف عنها أنها مهلة لغير الله، فإن اليهود والنصارى يذبحون الذبح العادي، فإذا ذبحوا الشيء لغير الله، وعرفت أنهم ذبحوا لغير الله لا يؤكل؛ لأن الله قال في المحرمات: وَمَا أُهِلَّ بِهِ لِغَيْرِ اللَّهِ [البقرة:173]. وهكذا ذبائح الشيوعيين فإنهم ملاحدة أكفر من الوثنيين؛ فلا تؤكل ذبيحتهم -نسأل الله العافية- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11282/حكم-الاكل-مع-غير-المسلمين-واكل-ما-اهل-لغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50601.mp3","categories":["الذكاة والصيد"]},{"id":13084,"question":"يقول هذا السائل: هل يجب على الإنسان إذا شاهد شاة، أو ما يماثلها مشرفة على الموت، فهل يذكيها، علمًا بأنها مريضة لا تؤكل، ماذا يفعل بها؟","title":"حكم ذبح الشاة المشرفة على الموت","answer":"الجواب:  إن ذكاها فلا بأس، وإن تركها فلا بأس، الأمر واسع، إن ذكاها لعل أحد يقبلها، ويأكل منها فلا بأس، وإن تركها تموت؛ فلا بأس، الأمر واسع، الحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11301/حكم-ذبح-الشاة-المشرفة-على-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50716.mp3","categories":["الذكاة والصيد"]},{"id":13119,"question":"يسأل ويقول: البعض عند ذكاة الحمام يمنع خروج الدم بقبضته عند رقبة الفراخ، ما حكم لحم هذا الذبح، أو هذا الذبيح بالأحرى؟","title":"حبس دم الذبيحة عند ذبحها","answer":"الجواب:  إذا كان منع خروج الدم؛ لا تصح الذبيحة، لابد أن يكون الدم مسفوحًا، لابد يراق الدم، لابد من إراقة دم الذبيحة، سواء كان ذبيحة من الأنعام، كالإبل والبقر والغنم، أو من الدجاج، أو من الطيور الأخرى، لابد من إسالة دمها، نعم؛ لأن الرسول  قال: ما أنهر الدم، وذكر اسم الله عليه؛ فكل معناه الذي ما ينهر الدم لا يؤكل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11342/حبس-دم-الذبيحة-عند-ذبحها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47314.mp3","categories":["الذكاة والصيد"]},{"id":13303,"question":"السائل (ع. ع) مصري الجنسية يقول: هل من الحلال للنساء أن تقوم بذبح الطيور، أو اللحم المحلل، جزاكم الله خيرًا؟","title":"هل يحل للنساء أن تذبح الطيور؟","answer":"الجواب:  لا بأس في حق النساء، وحق الرجال، الذبح تذبح المرأة، ويذبح الرجل الخروف والدجاج والحمام وغير ذلك مما أباح الله، النبي ﷺ أقر ذبيحة المرأة إذا ذبحت، وهي تحسن الذبح؛ فلا بأس، ليس خاصًا بالرجال، إذا كانت تحسن الذبح تذبح الذبيحة المذبح الشرعي بالسكين الحادة، فلا بأس مثل الرجل لا فرق في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11589/هل-يحل-للنساء-ان-تذبح-الطيور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52202.mp3","categories":["الذكاة والصيد"]},{"id":13555,"question":"السائل يقول في هذا  عند ذبح الأضحية -يا سماحة الشيخ- يقوم بعض الناس في القرية بالتكبير عليها ويقولون: من الضرورة أن نوجهها إلى القبلة، أفيدونا في ذلك مأجورين.","title":"حكم توجيه الأضحية إلى القبلة عند الذبح","answer":"الجواب: السنة: أن يقول: باسم الله، والله أكبر، كما كان النبي ﷺ يفعل عند الضحية، وعند غيرها، والسنة توجيهها إلى القبلة، كل هذا سنة، الضحية وغيرها من الذبائح والهدي، وحتى الذبيحة التي للأكل يوجهها للقبلة، ويقول: باسم الله، والله أكبر تأسيًا بالنبي ﷺ في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11885/حكم-توجيه-الاضحية-الى-القبلة-عند-الذبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53214.mp3","categories":["الذكاة والصيد"]},{"id":13602,"question":"تقول أختنا: الطيور، أو الحيوانات التي تسقط من أعلى، وتصاب بجرح، أو كسر؛ تكون حركتها أحيانًا مثل السليمة، فهل يجوز الأكل منها؟","title":"حكم أكل الطيور المجروحة بعد ذكاتها","answer":"الجواب: نعم، إذا أمسكها وذبحها حلت، إذا سقطت الحمامة، أو غيرها من الطيور المباحة من شجرة، أو من جبل، وأمسكها، وذبحها وهي حية؛ حلت ولو فيها جرح، ولو كان فيها جرح. نعم.","link":"https://binbaz.org.sa/fatwas/11937/حكم-اكل-الطيور-المجروحة-بعد-ذكاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48012.mp3","categories":["الذكاة والصيد"]},{"id":13707,"question":"تقول السائلة في الآية الكريمة: حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ [المائدة:3] إلى آخر الآية.. تقول: في أحد الأيام أكلت لحم ذبح لغير الله، وأنا لا أعرف بأنه ذبح لغير الله، ولم أعلم إلا بعد فترة من إحدى الجارات، حيث عزمت تلك المرأة بعض الناس، وأنا ذهبت إليهم، وأكلت معهم هذا اللحم، ولا أدري هل ذكر فيه اسم الله، أم لا، ولكنني أكلت، ووجهوني في سؤالي.","title":"حكم الأكل من اللحم المذبوح لغير الله","answer":"الجواب: إذا كان المقدم للحم مسلمًا، أو من أهل الكتاب؛ فلا بأس أن يأكل الإنسان، ما لم يعلم أنه ذبح لغير الله، أو تعمد ذابحه ترك اسم الله. أما لو ترك اسم الله ناسيًا، أو جاهلاً فلا يضر، فلك الأكل من اللحم الذي يقدم من المسلمين؛ لأن الأصل السلامة، والشك في المسلمين لا ينبغي. أما إذا علم الإنسان أن هذه الذبيحة ذبحت لغير الله؛ للأصنام أو لأصحاب القبور، أو للجن؛ حرمت، صارت ميتة، لا يجوز. أما كونها ذبيحة يهودي، أو نصراني الله أباح الطعام لنا.. طعام أهل الكتاب لنا نعم، إلا إذا علمنا أنه محرم، إذا علمنا أنهم ذبحوا لغير الله، أو تعمدوا ترك اسم الله عليه عمدًا، وهم يعلمون الحكم الشرعي. المقصود: أن هذا لا حرج فيه، أن يأكل الإنسان من اللحوم التي ذبحها المسلمون، أو أهل الكتاب ما لم يعلم أن هناك مانعًا شرعيًا منها.","link":"https://binbaz.org.sa/fatwas/12071/حكم-الاكل-من-اللحم-المذبوح-لغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54503.mp3","categories":["الذكاة والصيد"]},{"id":13751,"question":"من ضمن أسئلته هذا السؤال يقول سماحة الشيخ: هل ذبح الغنم التي لا تستطيع المشي هل يجوز، أم نتركها تموت بغير ذكاة؟","title":"حكم ذبح الغنم العاجزة عن المشي","answer":"الجواب: ذبحها أحسن لعلها تؤكل، ذبحها والتسمية في ذلك، وإعطاؤها الفقراء هذا أحسن، حتى ينتفع بها. نعم.","link":"https://binbaz.org.sa/fatwas/12115/حكم-ذبح-الغنم-العاجزة-عن-المشي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54601.mp3","categories":["الذكاة والصيد"]},{"id":13773,"question":"السائل في سؤاله الثاني يقول: إذا نسي المسلم أن يذكر اسم الله عند الذبح فهل ذبيحته هذه حرام، لا يجوز أكلها؟","title":"حكم نسيان التسمية عند الذبح","answer":"الجواب: إذا نسي المسلم التسمية عند الذبح، أو عند الوضوء؛ فالذبح صحيح، والوضوء صحيح، والحمد لله، أو نسيها عند الهدي -عند الفدي فدية الحج- كل ذلك لا حرج، فالذبيحة صحيحة وحلال، والله يقول: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] قال الله: قد فعلت فالناسي معذور، والذبيحة حلال ضحية أو هدية أو عقيقة أو غير ذلك. نعم. وهكذا الجاهل الذي ما يعرف الأحكام الشرعية، الجاهل إذا ما سمى ذبيحته شرعية لأجل الجهل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12153/حكم-نسيان-التسمية-عند-الذبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53607.mp3","categories":["الذكاة والصيد"]},{"id":13850,"question":"اللحوم المستوردة كيف توجهوننا بخصوصها يا شيخ عبدالعزيز؟ السؤال لأخينا صاحب الرسالة السابقة.","title":"ما حكم أكل اللحوم المستوردة؟","answer":"الجواب: اللحوم المستوردة إن كانت من بلاد المجوس والوثنين، أو من بلاد الشيوعيين أو البوذيين أو أشباههم من الكفرة هذه لا تحل؛ لأن ذبيحتهم حرام، أما إذا كانت من بلاد النصارى واليهود فإنها تحل؛ لأن الله أباح لنا طعامهم وهو ذبائحهم، لكن بسبب أن كثيرًا من المجازر في أوروبا وأمريكا لا يهتمون بالذبح الشرعي وربما ذبحوا بالخنق أو بالصرع أو بالصعق أو بغير ذلك هذا يوجب للإنسان التوقف وأخذ الحيطة، فإذا تيسر له أن يستغني عن ذلك بالذبح الشرعي أو بالتماس المجازر المعروفة التي تذبح ذبحًا شرعيًا ويكتفي بها فهذا هو الذي ينبغي له، عملاً بقوله ﷺ: دع ما يريبك إلى ما لا يريبك، وقوله ﷺ: من اتقى الشبهات فقد استبرأ لدينه وعرضه، لكن لا تحرم ذبيحة أهل الكتاب إذا لم يعلم شيئًا؛ لأنها الأصل حلها لكن من باب الحيطة لوجود المجازر الكثيرة التي لا تبالي بالذبح الشرعي إذا احتاط في ذلك واشترى من المجازر المعروفة أو ذبح لنفسه يكون هذا هو الأحوط عملاً بالحديث المتقدم: دع ما يريبك إلى ما لا يريبك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12218/ما-حكم-اكل-اللحوم-المستوردة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60215.mp3","categories":["الذكاة والصيد"]},{"id":14106,"question":"يسأل أخونا من تونس فيقول: في بعض الحالات يحصل تجمع في مناسبة ويؤتى بطعام وفيه لحم لا يعرف هل ذابحه يصلي أم لا، هل نمتنع عن الأكل منه خشية أن يكون الذابح لا يصلي لكثرة تاركي الصلاة في مجتمع ما مثلاً، أو لكثرة المتساهلين بها؟ وجهونا جزاكم الله خيرًا.","title":"حكم الأكل من الذبيحة التي لا يعلم حال ذابحها","answer":"الجواب: إذا كنت بين مسلمين وفي بيت أخيك المسلم الذي لا تظن به إلا الخير فكل مما قدم إليك ولا تشك في أخيك ولا تحكم سوء الظن، أما إذا كنت في مجتمع لا يصلي فاحذر، إذا كنت في مجتمع لا يصلي أو في مجتمع كافر فلا تأكل ذبيحتهم، كل من الفاكهة والتمر ونحو ذلك مما لا تعلق له بالذبيحة، أما إذا كنت بين المسلمين وفي قرية مسلمة أو في جو مسلم فعليك بحسن الظن ودع عنك سوء الظن، الله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12541/حكم-الاكل-من-الذبيحة-التي-لا-يعلم-حال-ذابحها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61410.mp3","categories":["الذكاة والصيد"]},{"id":14529,"question":"اشترى رجل بقرة فذبحها، وبعد الذبح اتضح وجود عجل صغيرة في بطنها، قام الرجل بذبح ذلك العجل مع أمه. و هل يجوز أكل لحم العجل الصغير مع أمه، مع العلم أنه بقي في بطن أمه وهي ميتة مذبوحة حوالي نصف ساعة؟أفيدونا جزاكم الله خيرًا.","title":"ما حكم الجنين إذا ذبحت أمه؟","answer":"الجواب: العجل تابع لأمه، فإذا ذبحت الذبح الشرعي فهو حلال، ولا حاجة إلى ذبحه، إلا إذا خرج حيًا، فإنه يخير، إن شاء ذبحه، وإن شاء أبقاه، أما إذا كان مات بذبحها فإنه تبع لها، فهو حل، وهكذا ولد الشاة، ولد الناقة، إذا ذبحت أمه وخرج ميتًا فهو له حكمها حلال، طيب، ليس فيه بأس.  أما إن خرج حيًا فهو مخير، إن شاء ذبحه، وإن شاء أبقاه، واستمتع به، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13025/ما-حكم-الجنين-اذا-ذبحت-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63407.mp3","categories":["الذكاة والصيد"]},{"id":14679,"question":"المستمع عبدالرحمن سعيد عبود العمري، بعث برسالة ضمنها سؤالاً طويلًا يتلخص في السؤال عن الطريقة الصحيحة للذبيحة، ويقصد الذبح، كيف تكون؟ وذلك أنه رأى عدة طرق، ويرجو الطريقة الصحيحة الشرعية، جزاكم الله خيرًا.","title":"الطريقة الشرعية في الذبح","answer":"الجواب: إن كانت الذبيحة بقرة، أو من المعز والغنم، يذبحها على جنبها، يسدحها على جنبها الأيسر، ثم يضع رجله على رأسها، ثم ينحرها، يجعل رجله على رقبتها، ثم يمسك الرأس بيده ويذبحها الحلقوم والمريء، يقطع الحلقوم والمرئ والودجين، يعني: العرقين المحيطين بالحلقوم والمريء، هذه السنة، ويضع رجله على صفحتها حتى يكون أسهل عليها من الاضطراب.  ويكون الذبح بسكين حادة قوية بقوة، حتى لا يعذبها، ويكون في الحلق، يقطع الحلقوم والمريء والودجين، هذا الكمال، وإن قطع الحلقوم والمرئ كفى، وإن قطع معهما أحد الودجين كفى، ولكن الأفضل أنه يقطع الحلقوم والمريء والودجين، وهو ماسك الرأس بيده اليسرى، ويذبح باليمنى، ويضع رجله على صفحتها حتى لا تضطرب. وإن كان المذبوح بعيرًا يطعنه باللبة، بالحربة في لبته، الذي بين الصدر والرقبة، اللبة في محل الطعن والذبح، ولو ذبحها مثلما يذبح البقرة أجزأ، لكن كونه مع اللبة أفضل.  ويسمي الله عند الذبح، يقول: باسم الله، والله أكبر عند الذبح، باسم الله، والله أكبر، هذا هو المشروع في الذبح.\nويسمى الطعن في اللبة نحرًا، ويسمى قطع الحلقوم والمريء بالسكين يسمى ذبحًا، ويكون الأفضل مستقبل القبلة، يوجهها إلى القبلة. هذا هو الأفضل، ولو ذبح إلى غير القبلة أجزأت، لكن كونها إلى القبلة أفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13165/الطريقة-الشرعية-في-الذبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48916.mp3","categories":["الذكاة والصيد"]},{"id":14867,"question":"من نيجيريا هذه رسالة بعث بها أحد الإخوة المستمعين هو أبو بكر علي محمد علي يقول في رسالته: هل يجوز للإنسان أن يأكل ذبيحة من يعلق التمائم؟","title":"حكم أكل ذبيحة من يعلق التمائم","answer":"الجواب: هذا فيه تفصيل:  إذا كان يعرف من معلق التمائم أنه يشرك بالله، ويعتقد في التمائم أنها تنفع وتضر دون الله، ويعتمد عليها دون الله، أو يعتقد في الأموات يدعوهم، ويستغيث لهم، وينذر لهم، أو في الأشجار والأصنام، أو في الجن يدعوهم، ويستغيث بهم هذا لا تؤكل ذبيحته. أما إن كان يعلقها عادية؛ لأنه يرى أنها من أسباب النفع، ولا يعتقد أنها هي الضارة النافعة، ولا يتعاطى شيء من الشرك، فهذا تؤكل ذبيحته؛ لأن تعليق التمائم من الشرك الأصغر، نعم.","link":"https://binbaz.org.sa/fatwas/13371/حكم-اكل-ذبيحة-من-يعلق-التماىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64514.mp3","categories":["الذكاة والصيد"]},{"id":14869,"question":"من نيجيريا هذه رسالة بعث بها أحد الإخوة المستمعين هو أبو بكر علي محمد علي يقول في رسالته: هل يجوز للإنسان أن يأكل ذبيحة من يعلق التمائم؟","title":"حكم أكل ذبيحة من يعلق التمائم","answer":"الجواب: هذا فيه تفصيل:  إذا كان يعرف من معلق التمائم أنه يشرك بالله، ويعتقد في التمائم أنها تنفع وتضر دون الله، ويعتمد عليها دون الله، أو يعتقد في الأموات يدعوهم، ويستغيث لهم، وينذر لهم، أو في الأشجار والأصنام، أو في الجن يدعوهم، ويستغيث بهم هذا لا تؤكل ذبيحته. أما إن كان يعلقها عادية؛ لأنه يرى أنها من أسباب النفع، ولا يعتقد أنها هي الضارة النافعة، ولا يتعاطى شيء من الشرك، فهذا تؤكل ذبيحته؛ لأن تعليق التمائم من الشرك الأصغر، نعم.","link":"https://binbaz.org.sa/fatwas/13371/حكم-اكل-ذبيحة-من-يعلق-التماىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64514.mp3","categories":["الذكاة والصيد"]},{"id":14872,"question":"هل يجوز للإنسان أن يأكل ذبيحة أهل الطريقة التيجانية؟","title":"حكم أكل ذبيحة أهل الطريقة التيجانية","answer":"الجواب: الذي يظهر لنا أنها لا تؤكل ذبيحتهم؛ لأن ظاهرهم عدم الإسلام في الصحيح؛ لأن بدعتهم تخرجهم من الإسلام، فينبغي تبصيرهم وتذكيرهم حتى يدعوا هذه البدعة بدعة التيجانية؛ لأن فيها شرًا عظيمًا؛ ولأنها في الحقيقة تخرج من الإسلام، فلا ينبغي أن يتخذوا أئمة، ولا ينبغي أن تؤكل ذبائحهم، حتى يدعوا هذه الطريقة الخبيثة التي يسمونها الطريقة التيجانية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13372/حكم-اكل-ذبيحة-اهل-الطريقة-التيجانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64515.mp3","categories":["الذكاة والصيد"]},{"id":14963,"question":"وردتنا رسالة من المرسل حمد سليم العامري، يتحدث فيها عن أكل اللحوم غير المذبوحة على الطريقة الإسلامية، خارج البلاد الإسلامية، يقول في رسالته:بعض المسلمين لما يذهبوا إلى الخارج يضطروا إلى أكل اللحوم، وهذه اللحوم مذبوحة على غير الطريقة الإسلامية، فما الحكم فيها؟وشكرًا لكم.","title":"حكم اللحوم المذبوحة في غير البلاد الإسلامية","answer":"الجواب: البلاد تختلف؛ إن كانت البلدة بلد نصارى أو يهود؛ فهؤلاء ذبيحتهم حل لنا، الله سبحانه أباح لنا طعام أهل الكتاب، وهم اليهود والنصارى، فإذا كنت في بلد من بلادهم: كأمريكا فرنسا، هولندا بلجيكا إنجلترا، وأشباه ذلك؛ فإنك تأكل ما وجدت من اللحوم، إلا إذا علمت أنه من الخنزير فلا تأكل، أو علمت أنهم ذبحوه بالخنق أو بالصرع من دون ذبح فلا تأكل.  أما إذا لم تعلم فإنك تأكل، وهو حل لك، وعليك أن تتحرى تسأل المسؤول هل هذا اللحم خنزير أو بقر أو غنم، فإذا علمت أنه بقر أو غنم أو دلك غيرك على ذلك كل، وإذا علمت أنه خنزير فدعه، ولا تأكل منه. ولا ينبغي التكلف والتشدد الذي يخالف أمر الله، فإن الله أباح لنا سبحانه طعام أهل الكتاب، وهو يعلم حالهم وكفرهم وضلالهم وتحريفهم الكلم عن مواضعه، وعدم قيامهم بالواجب، هو يعلم هذا ، هم كفار كفرهم الله في كتابه العظيم، ومع هذا أباح لنا طعامهم، فعلينا أن نقبل هذه الرخصة من الله، وأن لا نشدد على أنفسنا، بل ما علمنا أنه محرم تركناه، وما لم نعلم فالأصل إباحته، والحمد لله. أما إذا كنت في بلاد الشيوعيين في بلاد الوثنيين؛ فلا تأكل إلا ما ذبحه المسلمون، أو ذبحه أهل الكتاب، مثل الهند، مثل بلاد السوفيت، مثل الصين، مثل بلغاريا، وما أشبه ذلك من البلاد التي فيها الشيوعيون والوثنيون، فإن ذبائحهم غير حلال لا تحل لنا، فعليك أن تتحرز في ذلك، وألا تأكل منها، إلا ما علمت أنه ذبحه مسلم أو كتابي، نعم. المقدم: لكن هل يجب على المسلم أن يسأل في البلاد الغربية مثلًا التي هي ليست بلاد الشيوعية؟\nالشيخ: إذا خاف أن يكون خنزيرًا يسأل يتحرى، حتى لا يأكل الخنزير، أما الذبيحة فقد لا يتيسر له من يخبره عن الذبيحة، قد يكون هذا فيه مشقة كبرى؛ لأن الغالب قد يكون ما عندهم علم، وقد يكون أيضًا في خبرهم، غير موثوق به في الخبر؛ لأنهم ما بين عامل أو شبهه من لا يعرف الحقائق، فإذا تيسر من يعرف الحقائق عن هذا المطعم المعين وسأله فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/13466/حكم-اللحوم-المذبوحة-في-غير-البلاد-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_650/nour_65005.mp3","categories":["الذكاة والصيد"]},{"id":15138,"question":"أيضًا يقول: ما حكم أكل اللحوم المستوردة، والاتجار بها، والموجودة حاليًا في الأسواق المبرد منها والمثلج والمفروم، وكذلك الدجاج والطيور والأرانب... إلى آخره؟","title":"حكم أكل اللحوم المستوردة والاتجار فيها","answer":"الجواب: كل ما يرد من بلاد أهل الكتاب فلا بأس ببيعه وشرائه وأكله؛ لأن الله سبحانه أباح لنا طعامهم بنص القرآن، فما جاءنا من بلادهم من إنجلترا أو فرنسا أو أمريكا أو أشباهها، فهو حل لنا، ولنا بيعه والتصرف فيه؛ لأن الأصل إباحة طعامهم إلا ما علمنا أنه من شركة تذبح على غير الشرع، فإذا علمنا ذلك فلا، إذا علمت أن هذه اللحوم جاءت من شركة معلومة لا تقطع الرأس، أو تخنق الدابة خنقًا، أو ما أشبه ذلك، فهذا لا يحل للمسلم، مثل ذبيحة المسلم المخنوقة، المسلم لو خنقها أو ماتت بطريق آخر كالمتردية والنطيحة حرمت، ولو أنه مسلم، فاليهودي والنصراني من باب أولى.  أما إذا لم تعلم أنها ذبحت على غير الشرع، بل جاءت مقطوعة الرأس، ولا تعلم كيف ذبحوها، فالأصل حلها، ولا حرج في أكلها وبيعها. أما ما يرد من البلدان الأخرى مثل البلدان الشيوعية كالصين الشعبية وبلغاريا، رومانيا، فهذه ذبيحتهم لا تحل، هؤلاء ذبيحتهم لا تحل، وهكذا البلاد الوثنية كالهند وأشباه ذلك من البلاد الوثنية كوريا، اليابان فهذه بلاد وثنية ذبائحهم لا تحل إلا إذا تولاها مسلم أو كتابي، نعم. المقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13647/حكم-اكل-اللحوم-المستوردة-والاتجار-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66505.mp3","categories":["الذكاة والصيد"]},{"id":15139,"question":"أيضًا يقول: ما حكم أكل اللحوم المستوردة، والاتجار بها، والموجودة حاليًا في الأسواق المبرد منها والمثلج والمفروم، وكذلك الدجاج والطيور والأرانب... إلى آخره؟","title":"حكم أكل اللحوم المستوردة والاتجار فيها","answer":"الجواب: كل ما يرد من بلاد أهل الكتاب فلا بأس ببيعه وشرائه وأكله؛ لأن الله سبحانه أباح لنا طعامهم بنص القرآن، فما جاءنا من بلادهم من إنجلترا أو فرنسا أو أمريكا أو أشباهها، فهو حل لنا، ولنا بيعه والتصرف فيه؛ لأن الأصل إباحة طعامهم إلا ما علمنا أنه من شركة تذبح على غير الشرع، فإذا علمنا ذلك فلا، إذا علمت أن هذه اللحوم جاءت من شركة معلومة لا تقطع الرأس، أو تخنق الدابة خنقًا، أو ما أشبه ذلك، فهذا لا يحل للمسلم، مثل ذبيحة المسلم المخنوقة، المسلم لو خنقها أو ماتت بطريق آخر كالمتردية والنطيحة حرمت، ولو أنه مسلم، فاليهودي والنصراني من باب أولى.  أما إذا لم تعلم أنها ذبحت على غير الشرع، بل جاءت مقطوعة الرأس، ولا تعلم كيف ذبحوها، فالأصل حلها، ولا حرج في أكلها وبيعها. أما ما يرد من البلدان الأخرى مثل البلدان الشيوعية كالصين الشعبية وبلغاريا، رومانيا، فهذه ذبيحتهم لا تحل، هؤلاء ذبيحتهم لا تحل، وهكذا البلاد الوثنية كالهند وأشباه ذلك من البلاد الوثنية كوريا، اليابان فهذه بلاد وثنية ذبائحهم لا تحل إلا إذا تولاها مسلم أو كتابي، نعم. المقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13647/حكم-اكل-اللحوم-المستوردة-والاتجار-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66505.mp3","categories":["الذكاة والصيد"]},{"id":15460,"question":"هذا سؤال بعث به المستمع العمري محمد، مغربي الجنسية، ومقيم في فرنسا، له في الواقع سؤالان أولهما: يقول فيه: تعرفون عادة الذين أوتوا الكتاب مخالفة لعادة العرب في ذبح الذبائح، ولكن نحن نأكل من لحوم بقرهم وأغنامهم ومعزهم فهل علينا إثم في ذلك أم لا؟","title":"حكم الأكل من ذبائح أهل الكتاب","answer":"الجواب: الله سبحانه أباح لنا طعام أهل الكتاب، فقال : الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ[المائدة:5] وأهل الكتاب هم اليهود والنصارى، وقد غيروا وبدلوا قبل بعث النبي ﷺ وقد حرفوا، ومع ذلك أباح الله لنا طعامهم، والمحصنات من نسائهم. فدل ذلك على أنه لا حرج علينا أن نأكل من طعامهم، وطعامهم ذبائحهم، أما الفواكه وأشباهها هذه تؤكل من جميع أجناس الناس، حتى من غير أهل الكتاب، حتى الوثنيون بأصنافهم لا بأس أن نأكل من فواكههم وحبوبهم وثمارهم لا بأس، بينما المحرم الذبائح، فالذبائح تحرم من غير أهل الكتاب كالوثنيين والمجوس ومن لا دين له، هؤلاء ذبائحهم لا تحل للمسلمين مطلقًا، وإنما يباح لنا ذبائح أهل الكتاب خاصة اليهود والنصارى. فإذا كنت لا تعلم كيف ذبحوا فكل، والحمد لله، ولا تسأل ما دمت تعرف أن هذا من ذبائح أهل الكتاب اليهود أو النصارى، فهي حل لك، لكن متى علمت أنهم ذبحوها ذبحًا غير شرعي مثلًا خنقوها خنقًا فلا تأكل؛ لأنهم ليسوا أعز من المسلمين، والمسلم لو خنقها حرمت، ولو ضرب رأسها حتى ماتت حرمت، ولو ضرب بطنها حتى ماتت حرمت، وهو مسلم كيف باليهودي والنصراني؟ اليهودي والنصراني أنقص من المسلم، فإذا أخل بالذبح، وعرفت ذلك أنه ذبحها ذبحًا غير شرعي بأن خنقها أو ضربها حتى ماتت فلا تحل.\nالمقدم: أو بوسيلة الكهرباء، مثلًا.\nالشيخ: أو بوسيلة الكهرباء أخذ دمها نشف دمها من عروقها حتى ماتت، أو ضرب رأسها حتى فقأ رأسها، فلا تحل. وكذلك لو تعاطى نوعًا آخر غير هذه الأشياء المعروفة، لكن غير الذبح أو ذبحها لغير الله أهل بها للمسيح أو للعزير أو لأصنام أخرى لا تحل؛ لأن الله حرم ما أهل به لغير الله. أما إذا لم تعلم فأنت تأكل، أو علمت أنهم ذبحوها ذبحًا شرعيًا في الحلقوم والمريء والودجين الذبح الشرعي هكذا في الحلقوم والمريء والودجين هذا الذبح الشرعي، إذا قطع الحلقوم والمريء والودجين هذا ذبح كامل، وإن قطع الحلقوم والمريء أجزأت، وإن قطع معهما أحد الودجين كان ذلك طيبًا، ولكن الكمال في الذبح أن يقطع الحلقوم والمريء والودجين جميعًا، وهما العرقان المحيطان بالعنق، هذه الأربعة الأشياء إذا قطعهما الذابح كان أكمل، وإن اكتفى بالحلقوم والمريء حلت على الصحيح، وإن قطع معهما أحد الودجين كذلك حلت، وإن قطعها قطع الأربعة كلها صار هذا أكمل في الذبح. والسنة أن يسمي يقول: باسم الله، بل هذا واجب عند التسمية يسمي الله، فإذا نسيها أو جهل الحكم فلا حرج لو ذبح، ولم يسم جاهلًا أو ناسيًا سواء كان مسلمًا أو كافرًا فلا حرج، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13978/حكم-الاكل-من-ذباىح-اهل-الكتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_701/nour_70102.mp3","categories":["الذكاة والصيد"]},{"id":15667,"question":"أيضًا يسألان عن نفخ البهيمة بعد ذبحها من أجل السلخ، هل هذا جائز، أو لا؟","title":"حكم نفخ البهيمة بعد ذبحها من أجل السلخ","answer":"الجواب: نعم، إذا دعت إليه الحاجة لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14211/حكم-نفخ-البهيمة-بعد-ذبحها-من-اجل-السلخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70516.mp3","categories":["الذكاة والصيد"]},{"id":15741,"question":"على بركة الله، نبدأ هذا اللقاء برسالة وصلت من الأردن المستمع نضال محمد، يقول في هذا السؤال سماحة الشيخ: هل يجوز أن تذبح المرأة؟ وما معنى قوله تعالى: فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2].","title":"حكم ذبيحة المرأة والجنب","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، وصلى الله وسلم على عبده ورسوله نبينا محمد وعلى آله وأصحابه ومن تبعهم بإحسان إلى يوم الدين، أما بعد: فلا حرج في ذبيحة المرأة إذا كانت تحسن ذلك، رخص النبي في ذلك -عليه الصلاة والسلام-، وأمر بأكل ذبيحتها، إذا كانت تحسن ذلك فلا بأس كالرجل. وأما قوله -جل وعلا-: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2] ما هو معناه الخصوص به، النبي ﷺ ينحر، والصحابة نحروا، كل مسلم ينحر، والنحر: الذبح، فالرجل يذبح، والمرأة تذبح إذا كان كل امرئ يحسن الذبح، أما الذي لا يحسن الذبح من الرجال والنساء لا يؤمر بالذبح يلتمس غيره.\nالمقدم: أحسن الله إليكم، هل يجوز أن يذبح الإنسان وهو على جنابة، وهو عليه جنابة؟\nالشيخ: نعم، لكن يسمي الله يقول: باسم الله، ولو على جنابة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14324/حكم-ذبيحة-المراة-والجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57504.mp3","categories":["الذكاة والصيد"]},{"id":15863,"question":"نختم هذا اللقاء بهذا السؤال -سماحة الشيخ- لهذا السائل يقول: بالنسبة للصيد بالسلاح الناري -كالبارود وغيره-، علمًا بأننا نرى الطير يكون ميتًا على الأرض من طلقة هذا السلاح، فهل يؤكل لحم مثل هذا الطير؟ مأجورين سماحة الشيخ.","title":"حكم الصيد بالسلاح الناري","answer":"الجواب: نعم، نعم؛ لأنه محدد، الفشكة تصيب الحد فتخرج الدم، تخرج الدم، نعم، والنبي ﷺ قال: ما أنهر الدم، وذكر اسم الله فكل فهذا السلاح ينهر الدم مع التسمية يحل، أما لو ترك التسمية ناسيًا فلا شيء عليه، نعم. المقدم: أحسن الله لكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14454/حكم-الصيد-بالسلاح-الناري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57625.mp3","categories":["الذكاة والصيد"]},{"id":16275,"question":"من المستمعة (ف. م. ع) من عدن رسالة ضمنتها بعض الأسئلة في أحدها تسأل، وتقول: قال الله تعالى: وَلا تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهِ وَإِنَّهُ لَفِسْقٌ [الأنعام:121] وسؤالي: إذا قدم لي لحم في عزومة، أو هدية، أو مشترى من السوق، ولا أعلم عن ذبحه شيئًا، وهل الذي ذبح يصلي أو لا، هل يكفي أن أبسمل وآكل؟","title":"مَنْ تحل ذبيحته ومَنْ تحرم؟","answer":"الجواب: إذا كان ذلك بين المسلمين فكلي، والحمد لله؛ لأن الأصل أنها ذبيحة مسلم؛ فلا حرج عليك. أما إذا كان البلد بلد كفر، يتولى الذبح كفار، فهذا فيه تفصيل: إن كانوا من أهل الكتاب: يهود، أو نصارى؛ فذبيحتهم حلال، إلا إذا علمت، أو علم الآكل غيرك، إذا علم أنهم ذبحوها لغير الله ذبحوها باسم المسيح، أو باسم العزير، أو ما أشبه ذلك؛ فلا يؤكل. أما إذا لم يعلم الآكل فالحمد لله، الله أباح طعام أهل الكتاب، قال -جل وعلا-: وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ [المائدة:5]، فطعام أهل الكتاب حل لنا، وهم اليهود والنصارى، إلا أن نعلم أنهم ذبحوا ذبحًا غير شرعي، خنقوها، ضربوها بالحديد حتى ماتت، هذا لا يؤكل حتى ولو فعلها مسلم ما تؤكل. أما إذا لم نعلم فذبيحتهم لنا حل، كذبيحة المسلم، حتى نعلم أن المسلم، أو اليهودي، أو النصراني ذبحوها ذبحًا غير شرعي، فإذا لم نعلم؛ فالأصل الحل. وكذلك إذا كانت الذبيحة من وثني يعبد القبور، يستغيث بالأموات، يدعو الأموات، يدعو الجن، لا تؤكل ذبيحته، أو لا يصلي، لا تؤكل ذبيحته؛ لأن ترك الصلاة على الأصح كفر، وإن لم يجحد وجوبها، أما إذا جحد وجوبها؛ كفر عند الجميع عند جميع العلماء، لكن إذا كان لا يصلي، ويقول: إنها واجبة؛ هذا يكفر عند جمع من أهل العلم، وهو الأصح، والأظهر في الدليل. وهكذا المسلم لو تعمد ترك التسمية عمدًا، وهو يعلم لا تؤكل ذبيحته، أما إذا كان جاهلًا، أو ناسيًا؛ فلا حرج، لابد من التسمية عند الذبح يقول: باسم الله، والله أكبر، لكن لو تركها المسلم ناسيًا، أو جاهلًا، ما يعرف الحكم الشرعي؛ ذبيحته حلال. أو ذبح الصيد، ولم يسم جاهلًا، أو ناسيًا، رمى الصيد، فقتله، ولكن نسي التسمية، أو جهل الحكم؛ فالصيد حلال، أما لو تعمد مسلم، وهو يعلم الحكم الشرعي أنه يجب عليه أن يسمي، وتساهل.. ما يبالي تكون ذبيحته غير شرعية؛ لا تؤكل. أما إذا كان الذين قدموا الطعام حدثاء عهد بالإسلام، عندهم بعض الجهل، وعندك شك في تسميتهم؛ يكفي أن تسمي تقول: باسم الله، سئل النبي ﷺ عن قوم حدثاء عهد بالإسلام لا .... قالت لهم عائشة، قد سألت عائشة عن هذا، قالت: لا ندري، أذكروا اسم الله، أم لا؟ قال: سموا الله أنتم، وكلوا الأصل الإباحة، الحمد لله، سموا الله أنتم وكلوا. فالحاصل: أن الذبيحة فيها تفصيل على حسب حال البلد: فإذا كان أهل البلد مسلمين، أو أهل كتاب، من اليهود، والنصارى؛ فالذبيحة حلال، الأصل فيها الحل، حتى تعلم شيئًا يحرمها عليك.  أما إذا كانت البلد يتولى الذبح فيها الكفار، أو بلاد كفار غير اليهود والنصارى؛ فلا تأكل حتى تعلم أن ذابحها مسلم، أو يهودي، أو نصراني، وحتى تعلم أن هذا الذابح الذي تولى ذبحها ليس ممن تحرم ذبيحته، بل هو إما يهودي، أو نصراني، أو مسلم. أما إذا كان الذي يذبحون أناس معروفون، عباد أوثان، أو لا يصلون، من عباد القبور؛ فلا تأكل ذبيحتهم إذا كانوا معروفين بهذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14974/من-تحل-ذبيحته-ومن-تحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80906.mp3","categories":["الذكاة والصيد"]},{"id":16421,"question":"هذا سائل للبرنامج، المملكة العربية السعودية برنامج نور على الدرب، يقول في هذا السؤال لفضيلة الشيخ: هل يجوز للمرأة أن تذبح؟ وهل يؤكل مما ذبحته المرأة؟","title":"جواز ذبيحة المرأة","answer":"الجواب: نعم، لها أن تذبح، إذا كانت مسلمة، أو كتابية لها أن تذبح، وعليها أن تسمي الله كالرجل، النبي ﷺ أقر ذبيحة المرأة، لا حرج في ذلك كالرجل، تذكر الله، وتسمي، وتذبح، سواء كانت مسلمة، أو كتابية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15116/جواز-ذبيحة-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58124.mp3","categories":["الذكاة والصيد"]},{"id":16610,"question":"ماذا أقول عند ذبح الذبيحة؟","title":"الذكر الذي يقول عند الذبح","answer":"الجواب: تقول عند ذبح الذبيحة: باسم الله، والله أكبر، ثم تذبح، باسم الله والله أكبر، هكذا كان يفعل النبي ﷺ تضع رجلك على صفحة العنق، ثم تمسك رأسها، وتذبح بيدك اليمنى أفضل، هذا هو السنة، وإن كانت ضحية قلت: عن فلان، أو عني وأهل بيتي، وإن كانت عقيقة قلت: عن ولدي فلان، أو عن بنتي فلانة، وإن كانت هدية يعني: عن حج وعمرة قلت: باسم الله والله أكبر، وناوي المتعة، تنوي الهدي، هدي التمتع، أو القران حسب ما في قلبك، وإن كانت عن نذر، نويت بالنذر أنها عن النذر الذي نذرته، نعم. المقدم: جزاكم الله خيرًا، ولا حرج أن يتلفظ بالنية حينئذ؟ الشيخ:... يقول: عن فلان، أو عن فلانة، أو عن ولدي فلان ..... العقيقة، نعم. المقدم: جزاكم الله خيرًا، إذًا هذا مما يستثنى من التلفظ بالنية؟ الشيخ: نعم، نعم، هذا جاء... كان النبي يفعله ﷺ وكان يقول: اللهم تقبل من محمد وآل محمد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15341/الذكر-الذي-يقول-عند-الذبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75811.mp3","categories":["الذكاة والصيد"]},{"id":16612,"question":"هل يجب أن أستقبل بالذبيحة القبلة؟","title":"حكم استقبال القبلة عند الذبح","answer":"الجواب: هذا السنة، هذا الأفضل، ولا يجب، لكنه أفضل، هو الأفضل. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/15342/حكم-استقبال-القبلة-عند-الذبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75812.mp3","categories":["الذكاة والصيد"]},{"id":17091,"question":"من المستمع عبد القادر أبو بكر يونس رسالة ضمنها بعضًا من الأسئلة يقول: إنه ذبح دجاجة، ففصل الرأس عن الجسد، ويسأل عن حكم مثل هذا العمل؟","title":"مشروعية الذبح بآلة حادة وحرمته بالخنق","answer":"الجواب: لا بأس، هذا الذبح، إذا قطع رأسها بالسكين فلا بأس، مثل لو قطع رأس الشاة، أو البعير، أو البقرة لا بأس، المقصود في المذبح، إذا قطع رأسها بشيء محدد سكين لا بأس، أما بيده لا ما يجوز، هذا خنق، لكن إذا قطعها بالسكين، ونحوها من المحددات لا بأس بهذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15960/مشروعية-الذبح-بالة-حادة-وحرمته-بالخنق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83119.mp3","categories":["الذكاة والصيد"]},{"id":17423,"question":"رسالة من المستمع (ع. م) من جدة يقول: ناديت الجزار ليذبح لي ذبيحة، فذبحها متجهًا بها إلى الشمال، فهل ذلك يؤثر؟","title":"حكم الذبح إلى غير القبلة","answer":"الجواب: لا يؤثر، لا حرج في ذلك، الأفضل إلى القبلة، ولو ذبحها إلى غير القبلة فالذبح صحيح؛ لأن استقبال القبلة مستحب، وليس بلازم، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16284/حكم-الذبح-الى-غير-القبلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83514.mp3","categories":["الذكاة والصيد"]},{"id":17541,"question":"الرسالة التالية رسالة المستمع أحمد سالم الحامد من الإمارات العربية المتحدة، أخونا أحمد عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: ما حكم من يذبح الطيور باليد، أي: يفصل الرأس عن الجسم، يمسك الرأس بيد والجسم باليد الثانية، ثم يسحب بشدة، هل يحل الأكل بهذه الطريقة؟","title":"حكم أكل ما يذبح من الطيور باليد","answer":"الجواب: هذا ذبح منكر، المذبوح يكون ميتة، ما يحل؛ لقول النبي ﷺ: ما أنهر الدم وذكر اسم الله فكل ليس السن والظفر، فلا يجوز هكذا قلع الرأس باليد، لابد من محدد، لابد من المحدد ينهر الدم، فأما مثل هذا فيسمى خنقًا مثل الخنق، يعتبر خنقًا تكون به.. تكون ميتة، فلابد من كونه يذبحها بالسكين ونحو السكين من المحددات، إلا العظام والسن فلا، كما بينه النبي عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16501/حكم-اكل-ما-يذبح-من-الطيور-باليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_839/nour_83902.mp3","categories":["الذكاة والصيد"]},{"id":17689,"question":"هذا سائل للبرنامج الحقيقة أرسل بمجموعة من الأسئلة مقيم في المملكة العربية السعودية، يقول في هذا  هل يجوز أكل لحم البهائم أو الغنم التي تذبح على القبر وهذا الشخص متعمد الذبح لمن في القبر، وجهونا في ضوء هذا السؤال؟","title":"حكم الأكل مما ذبح لأصحاب القبور","answer":"الجواب: ما يذبح لغير الله لا يؤكل ميتة يكون ميتة، ما يذبح لأصحاب القبور أو للأصنام أو للجن هذا يكون ميتة لا يحل أكله، قال الله جل وعلا: حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ [المائدة:3] ما ذبح لغير الله يكون ميتة- نسأل الله العافية- وصاحبه مشرك عليه التوبة إلى الله جل وعلا، فالذبح لغير الله من الشرك، فعليه التوبة إلى الله والرجوع إليه، والذبيحة حرام.. نسأل الله العافية.\nالمقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16630/حكم-الاكل-مما-ذبح-لاصحاب-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59518.mp3","categories":["الذكاة والصيد"]},{"id":17833,"question":"هذا السائل محمد أحمد من اليمن يقول: سماحة الشيخ! نرجو من سماحتكم أن تفتونا ما هي الأشهر الحرم؟ وهل يجوز الصيد فيها لغير الحاج؟","title":"الأشهر الحرم وحكم الصيد فيها لغير المحرم","answer":"الجواب: الأشهر الحرم هي: ذو القعدة، وذو الحجة، والمحرم، ورجب؛ أربعة قال الله جل وعلا: إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللَّهِ اثْنَا عَشَرَ شَهْرًا فِي كِتَابِ اللَّهِ يَوْمَ خَلَقَ السَّمَوَاتِ وَالأَرْضَ مِنْهَا أَرْبَعَةٌ حُرُمٌ[التوبة:36]، هذه الأربعة؛ ثلاثة متوالية: ذو القعدة، وذو الحجة، والمحرم عاشوراء، والرابع فرد وهو رجب بين جمادى وشعبان، هذه الأربعة الحرم. والصيد فيها جائز، كان القتال فيها محرم، وكانت الجاهلية تحذر ذلك أيضًا، ثم نسخ عند الجمهور القتال فيها وصار القتال فيها جائزًا، والصحابة قاتلوا الروم وغير الروم ولم يحفظ عنهم أنهم تركوا القتال في الأشهر الحرم لعلمهم بأنه نسخ، أما الصيد فلا بأس في الأشهر الحرم، لكن لا يصيد في الحرم في مكة والمدينة، حرم مكة وحرم المدينة لا يصاد فيهما، ولكن في الأشهر لا بأس أن يصيد في عاشور، أو في ذي الحجة، أو في رجب، أو في محرم، لا حرج في ذلك. نعم.\nالمقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16826/الاشهر-الحرم-وحكم-الصيد-فيها-لغير-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77906.mp3","categories":["الذكاة والصيد"]},{"id":18431,"question":"يسأل أخونا ويقول: إني حلفت على المصحف، وحلفت بالله أن لا أصيد طيرًا ولا حيوانًا، وقلت: إذا صدت شيئًا منه؛ فلحمه علي حرام وبعد مرور زمن رجعت إلى الصيد وأكلت لحمه، فهل اللحم يكون علي حرام؟ وماذا أفعل إذا كان هناك كفارة؟","title":"حكم أكل الصيد لمن حلف ألا يصطاده وألا يأكله","answer":"الجواب: هذه يمين خاطئة، لا يعول عليها ولا يحرم بها الحلال، وعليك كفارة اليمين؛ يقول النبي ﷺ: إذا حلفت على يمين فرأيت غيرها خيرًا منها فكفر عن يمينك وائت الذي هو خير متفق على صحته. ويقول عليه الصلاة والسلام: إني والله إن شاء الله لا أحلف على يمين فأرى غيرها خيرًا منها إلا كفرت عن يميني وأتيت الذي هو خير فأنت عليك كفارة يمين ولا بأس بأن تأكل الصيد، وتصيد الصيد الذي أباح الله، وليس في ذلك تحريم عليك، ويمينك خاطئة. نعم.","link":"https://binbaz.org.sa/fatwas/17511/حكم-اكل-الصيد-لمن-حلف-الا-يصطاده-والا-ياكله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_914/nour_91406.mp3","categories":["الذكاة والصيد"]},{"id":18482,"question":"يقول السائل: سمعت من بعض الناس بأنهم يقولون: إذا مرض الحيوان أو الشاة أو غير ذلك، وأنت لا تريد أن تأكلها فلا تذكيها، وإنما دعها تموت بدون ذكاة، هل هذا الكلام صحيح؟","title":"حكم تذكية الحيوان إذا كان مريضًا","answer":"الجواب: إن ذكاها فلا بأس، وإن تركها فلا بأس، لعلها تشفى، وإن ذكاها ليستريح من تعبها فلا بأس، لعل الله ييسر من يأكلها، قد يحتاج لها بعض الناس، وتؤكل؛ يذبحها الذبح الشرعي، قد يحتاجها بعض الفقراء.نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17574/حكم-تذكية-الحيوان-اذا-كان-مريضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78519.mp3","categories":["الذكاة والصيد"]},{"id":18878,"question":"يسأل أخونا أيضًا ويقول: إذا كان الجزار لا يصلي ولا يصوم، كيف يكون التعامل معه شرعًا؟","title":"حكم التعامل مع الجزار الذي لا يصلي","answer":"الجواب: من كان لا يصلي ولا يصوم لا يجعل جزارًا، ولا تشتري منه الذبيحة؛ ويمنع من الجزارة، وعلى ولاة الأمور أن يمنعوه، ولا يتولى الجزارة إلا مسلم معروف يؤدي الصلاة، ويتباعد عن كل ما يخل بدينه، هذا هو الواجب على ولاة الأمور في كل بلد، وأن لا يتولى الجزارة إلا مسلم معروف بديانته وأمانته وأدائه الصلاة، فلا يتولاها مشرك، ولا يتولاها من يترك الصلاة؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء، فالواجب على ولاة الأمور في كل بلد من بلاد المسلمين أن يتحروا فيمن يتولى الجزارة أن يكون مسلمًا، نعم.","link":"https://binbaz.org.sa/fatwas/18018/حكم-التعامل-مع-الجزار-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88002.mp3","categories":["الذكاة والصيد"]},{"id":19188,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: ابنكم أبو المنذر إسماعيل البشير سوداني مقيم في قطر، يقول في أحد أسئلته: عندنا في السودان يشترطون في الذبح أن يكون خلف الخرزة وهي النتوء البارز في حلقوم الذبيحة، وإذا ذبح أحد بهيمة، وفصل بين هذه الخرزة والرأس، فالناس لا يأكلون ذبيحته، ما مدى صحة هذا الكلام؟","title":"هل يشترط في الذبح أن يكون خلف النتوء البارز في حلقوم الذبيحة؟","answer":"الجواب: إذا قطع الحلقوم والمريء ولو فصل الخرزة فلا بأس، إذا قطع الحلقوم والمريء فذبيحته صحيحة، وإن قطع الأربعة الحلقوم والمريء والودجين كان أكمل وأكمل، سواء بقيت الخرزة أو قطعها معه، الأمر في هذا واسع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18366/هل-يشترط-في-الذبح-ان-يكون-خلف-النتوء-البارز-في-حلقوم-الذبيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93213.mp3","categories":["الذكاة والصيد"]},{"id":19201,"question":"من تبوك رسالة بعث بها أخونا: سالم سلامة محمد، له سؤالان في سؤاله الأول يسأل عن ذبيحة المرأة هل هي جائزة، وهل يؤكل منها، وما هو توجيهكم؟","title":"هل ذبيحة المرأة جائزة، وهل يؤكل منها؟","answer":"الجواب: نعم، ذبيحة المرأة جائزة إن كانت مسلمة أو كتابية من اليهود والنصارى. ذبيحة المسلمين من الرجال والنساء، وذبيحة أهل الكتاب من الرجال والنساء كلها جائزة، إذا كانت على الوجه الشرعي، وقد سئل النبي عن ذلك عليه الصلاة والسلام فأمضى ذبيحة المرأة عليه الصلاة والسلام. فهي كالرجل في كل الأحكام إلا ما خصه الدليل، فذبيحتها كالرجل، فإذا ذبحتها ذبحًا شرعيًا سواء كانت الذبيحة من الغنم أو من البقر أو من الإبل أو من الصيود أو من الدجاج أو الحمام، أو غير ذلك من المأكولات ذبيحتها جائزة إذا كانت على الوجه الشرعي، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18384/هل-ذبيحة-المراة-جاىزة-وهل-يوكل-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93304.mp3","categories":["الذكاة والصيد"]},{"id":19332,"question":"علمنا من حلقات البرنامج أن تارك الصلاة مطلقًا يعد كافرًا خارجًا عن الملة على الصحيح من الأقوال، فهل يحرم علينا أكل شيء مما ذبحه تارك الصلاة؟","title":"هل تجوز ذبيحة تارك الصلاة؟","answer":"الجواب: نعم، هذا مقتضى الحكم بتكفيره، فإن ذبيحة الكافر محرمة إلا أهل الكتاب وهم اليهود والنصارى خاصة، أما المرتد بترك الصلاة، أو بسب الدين، أو بالاستهزاء بالدين، أو بجحد وجوب الصلاة، أو بجحد وجوب الصيام رمضان، أو بغير هذا من نواقض الإسلام هذا حكمه حكم الوثنيين، بل أشد من الوثنيين، لا تؤكل ذبيحته إذا ذبح ذبيحة تكون حرامًا؛ لأنه مرتد ليس من جنس أهل الكتاب، بل المرتد فوق أهل الكتاب في الكفر فهو من جنس الوثنيين، ومن جنس المجوس لا تؤكل ذبيحته.","link":"https://binbaz.org.sa/fatwas/18539/هل-تجوز-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_897/nour_89703.mp3","categories":["حكم الصلاة وأهميتها","الذكاة والصيد"]},{"id":19411,"question":"نجد لحومًا كثيرة مذبوحة ومستوردة من بلادٍ غير إسلامية، هل نأكل منها ولا نفكر في عملية الذكاة؟","title":"حكم أكل اللحوم المستوردة","answer":"الجواب: إذا كانت اللحوم من بلاد أهل كتاب اليهود والنصارى فلا بأس؛ لأن الله أباح لنا طعامهم، وطعامهم ذبائحهم، فلا مانع أن نأكل منها إذا لم نعلم ما يمنع منها، فأما إذا علمنا أنها ذبحت خنقًا أو ضربًا في الرؤوس بالمطارق ونحوها وبالمسدسات أو صرعًا بالكهرباء فلا نأكل. وقد بلغنا من جهات كثيرة من الدعاة التابعين للرئاسة العامة للبحوث العلمية والإفتاء.. التابعين لنا، قد بلغنا عن جماعة منهم أن كثيرًا من المجازر تذبح على غير الطريق الشرعي في أمريكا وفي أوروبا، فإذا احتاط المؤمن ولم يأكل من هذه اللحوم يكون أحسن وأسلم، يقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك، من اتقى الشبهات فقد استبرأ لدينه وعرضه. فالمؤمن يحتاط لطعامه فإذا اشترى الحيوان حيًا، حيوان من الدجاج من الغنم وذبحها بنفسه يكون أولى وأفضل، أو اشترى من جزارين معروفين يذبحون على الطريقة الشرعية يكون هذا خير له وأحوط له، لأن اللحوم المستوردة التي قد تكون من مجازر غير سليمة، أما التحريم فلا يحرم إلا بالدليل إلا بيقين لكن هذا من باب ترك المشتبه. المقدم: جزاكم الله خيرًا. إذا كانت أغلفة هذه اللحوم سماحة الشيخ مكتوب عليها مذبوح على الطريقة الإسلامية؟ الشيخ: ولو كتب عليها لأنهم قد يتساهلون بهذا ... بضائعهم بهذه الكتابات قد يحصل تساهل فيها، إلا إذا علم أن هذا اللحم من مجزرة معلومة تذبح على الطريق الشرعي فلا بأس، أما مادام لا يعلم ذلك إنما تباع في الأسواق هكذا فالاحتياط تركها والأفضل للمؤمن التورع عنها دع ما يريبك إلى ما لا يريبك لقول النبي ﷺ: من اتقى الشبهات فقد استبرأ لدينه وعرضه . المقدم: بارك الله فيكم. إذًا الأولى فيما فهمت من سماحة الشيخ الانصراف إلى المنتج محليًا؟ الشيخ: نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18638/حكم-اكل-اللحوم-المستوردة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93607.mp3","categories":["الذكاة والصيد"]}]
